@import "tailwindcss";

/* Token dari design.md bagian 3. Nilai terang/gelap memakai light-dark(),
   jadi preferensi sistem bekerja tanpa JavaScript. Toggle manual cukup
   mengubah color-scheme di elemen html. */
@theme {
	--font-display: "Plus Jakarta Sans Variable", system-ui, sans-serif;
	--font-body: "Inter Variable", system-ui, sans-serif;
	--font-mono: "JetBrains Mono", ui-monospace, monospace;

	--radius-sm: 6px;
	--radius-md: 10px;
	--radius-lg: 14px;
	--radius-xl: 20px;

	--shadow-sm: 0 1px 2px rgba(31, 29, 26, 0.06);
	--shadow-md: 0 4px 14px rgba(31, 29, 26, 0.08);
	--shadow-lg: 0 12px 32px rgba(31, 29, 26, 0.14);
}

@theme inline {
	--color-bg: var(--bg);
	--color-surface: var(--surface);
	--color-surface-2: var(--surface-2);
	--color-line: var(--border);
	--color-line-strong: var(--border-strong);
	--color-ink: var(--text);
	--color-ink-muted: var(--text-muted);
	--color-accent: var(--accent);
	--color-accent-hover: var(--accent-hover);
	--color-accent-soft: var(--accent-soft);
	--color-accent-ink: var(--accent-text);
	--color-success: var(--success);
	--color-warning: var(--warning);
	--color-danger: var(--danger);
	--color-info: var(--info);
}

:root {
	color-scheme: light dark;

	--bg: light-dark(#faf8f5, #141311);
	--surface: light-dark(#ffffff, #1c1b18);
	--surface-2: light-dark(#f3f0ea, #252320);
	--border: light-dark(#e4dfd6, #34312c);
	--border-strong: light-dark(#cfc8bb, #4a463f);
	--text: light-dark(#1f1d1a, #f2efe9);
	--text-muted: light-dark(#6b665d, #a29c90);
	--text-faint: light-dark(#8e887d, #7a7468);

	--accent: light-dark(#e8890c, #f5a524);
	--accent-hover: light-dark(#cf7600, #ffb84d);
	--accent-soft: light-dark(#fdf0dc, #3a2a10);
	--accent-text: light-dark(#1f1d1a, #141311);

	--success: light-dark(#1e8e5a, #3dbe86);
	--warning: light-dark(#b7791f, #e0a940);
	--danger: light-dark(#c93c3c, #f06b6b);
	--info: light-dark(#2b6cb0, #63a4e8);

	--cat-gambar: #7c5cfc;
	--cat-diagram: #0ea5a4;
	--cat-dokumen: #e5484d;
	--cat-foto: #e5539b;
	--cat-berbagi: #2f80ed;
	--cat-generator: #e8890c;

	--space-1: 4px;
	--space-2: 8px;
	--space-3: 12px;
	--space-4: 16px;
	--space-5: 24px;
	--space-6: 32px;
	--space-7: 48px;
	--space-8: 64px;
	--space-9: 96px;

	--ring: 0 0 0 3px color-mix(in srgb, var(--accent) 35%, transparent);
	--ease: cubic-bezier(0.2, 0.8, 0.2, 1);
	--dur-fast: 120ms;
	--dur-base: 200ms;
	--dur-slow: 320ms;

	--page-max: 1200px;
	--header-h: 64px;
}

:root[data-theme="light"] {
	color-scheme: light;
}

:root[data-theme="dark"] {
	color-scheme: dark;
}

[data-category="gambar"] {
	--cat: var(--cat-gambar);
}
[data-category="diagram"] {
	--cat: var(--cat-diagram);
}
[data-category="dokumen"] {
	--cat: var(--cat-dokumen);
}
[data-category="foto"] {
	--cat: var(--cat-foto);
}
[data-category="berbagi"] {
	--cat: var(--cat-berbagi);
}
[data-category="generator"] {
	--cat: var(--cat-generator);
}

@layer base {
	*,
	*::before,
	*::after {
		box-sizing: border-box;
	}

	html {
		-webkit-text-size-adjust: 100%;
		scroll-behavior: smooth;
		scroll-padding-top: calc(var(--header-h) + var(--space-4));
	}

	body {
		margin: 0;
		background: var(--bg);
		color: var(--text);
		font-family: var(--font-body);
		font-size: 1rem;
		line-height: 1.625;
		-webkit-font-smoothing: antialiased;
	}

	h1,
	h2,
	h3 {
		font-family: var(--font-display);
		line-height: 1.2;
		text-wrap: balance;
		margin: 0;
	}

	p {
		margin: 0;
	}

	a {
		color: inherit;
	}

	:where(a[href], button:not(:disabled), summary, label[for], [role="button"]) {
		cursor: pointer;
	}

	:where(button:disabled, [aria-disabled="true"]) {
		cursor: not-allowed;
	}

	:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
		outline: 2px solid var(--accent);
		outline-offset: 2px;
	}

	img,
	svg {
		display: block;
	}

	@media (prefers-reduced-motion: reduce) {
		html {
			scroll-behavior: auto;
		}

		*,
		*::before,
		*::after {
			animation-duration: 0.01ms !important;
			animation-iteration-count: 1 !important;
			transition-duration: 0.01ms !important;
		}
	}
}

@layer components {
	.container {
		width: 100%;
		max-width: var(--page-max);
		margin-inline: auto;
		padding-inline: var(--space-4);
	}

	@media (min-width: 768px) {
		.container {
			padding-inline: var(--space-5);
		}
	}

	@media (min-width: 1024px) {
		.container {
			padding-inline: var(--space-6);
		}
	}

	.skip-link {
		position: absolute;
		left: var(--space-4);
		top: var(--space-2);
		z-index: 100;
		padding: var(--space-2) var(--space-4);
		border-radius: var(--radius-md);
		background: var(--accent);
		color: var(--accent-text);
		font-weight: 600;
		transform: translateY(-200%);
	}

	.skip-link:focus-visible {
		transform: translateY(0);
	}

	/* Header */
	.site-header {
		position: sticky;
		top: 0;
		z-index: 40;
		height: var(--header-h);
		background: var(--bg);
		border-bottom: 1px solid var(--border);
	}

	.header-inner {
		display: flex;
		align-items: center;
		gap: var(--space-3);
		height: 100%;
	}

	.brand {
		display: inline-flex;
		align-items: center;
		min-height: 44px;
		font-family: var(--font-display);
		font-size: 1.125rem;
		font-weight: 800;
		letter-spacing: -0.01em;
		text-decoration: none;
		color: var(--text);
	}

	.header-actions {
		display: flex;
		align-items: center;
		gap: var(--space-1);
		margin-left: auto;
	}

	.search-trigger {
		display: none;
		flex: 1;
		max-width: 420px;
		align-items: center;
		gap: var(--space-2);
		min-height: 40px;
		padding: 0 var(--space-3);
		border: 1px solid var(--border);
		border-radius: var(--radius-md);
		background: var(--surface-2);
		color: var(--text-muted);
		font-family: var(--font-body);
		font-size: 0.875rem;
		text-align: left;
		transition:
			border-color var(--dur-fast) var(--ease),
			background-color var(--dur-fast) var(--ease);
	}

	.search-trigger:hover {
		border-color: var(--border-strong);
		background: var(--surface);
	}

	.kbd {
		margin-left: auto;
		padding: 2px var(--space-1);
		border: 1px solid var(--border-strong);
		border-radius: var(--radius-sm);
		font-family: var(--font-mono);
		font-size: 0.6875rem;
		color: var(--text-muted);
	}

	.icon-button {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		width: 44px;
		height: 44px;
		border: 1px solid transparent;
		border-radius: var(--radius-md);
		background: transparent;
		color: var(--text-muted);
		transition:
			background-color var(--dur-fast) var(--ease),
			color var(--dur-fast) var(--ease);
	}

	.icon-button:hover {
		background: var(--surface-2);
		color: var(--text);
	}

	@media (min-width: 768px) {
		.search-trigger {
			display: inline-flex;
		}
	}

	/* Tombol */
	.btn {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		gap: var(--space-2);
		min-height: 44px;
		padding: 0 var(--space-4);
		border: 1px solid transparent;
		border-radius: var(--radius-md);
		font-family: var(--font-display);
		font-size: 0.9375rem;
		font-weight: 600;
		line-height: 1;
		text-decoration: none;
		transition:
			background-color var(--dur-fast) var(--ease),
			border-color var(--dur-fast) var(--ease),
			color var(--dur-fast) var(--ease);
	}

	.btn:active {
		transform: translateY(1px);
	}

	.btn[disabled],
	.btn[aria-disabled="true"] {
		opacity: 0.45;
		pointer-events: none;
	}

	.btn--primary {
		background: var(--accent);
		color: var(--accent-text);
	}

	.btn--primary:hover {
		background: var(--accent-hover);
	}

	.btn--secondary {
		background: var(--surface);
		border-color: var(--border-strong);
		color: var(--text);
	}

	.btn--secondary:hover {
		background: var(--surface-2);
	}

	.btn--ghost {
		background: transparent;
		color: var(--text-muted);
	}

	.btn--ghost:hover {
		background: var(--surface-2);
		color: var(--text);
	}

	.btn--danger {
		background: transparent;
		border-color: currentColor;
		color: var(--danger);
	}

	/* Form */
	.field-label {
		display: block;
		margin-bottom: var(--space-1);
		font-size: 0.875rem;
		font-weight: 500;
	}

	.field-input {
		width: 100%;
		min-height: 44px;
		padding: 0 var(--space-3);
		border: 1px solid var(--border);
		border-radius: var(--radius-md);
		background: var(--surface-2);
		color: var(--text);
		font-family: var(--font-body);
		font-size: 1rem;
		line-height: 1.5;
		transition:
			border-color var(--dur-fast) var(--ease),
			box-shadow var(--dur-fast) var(--ease);
	}

	.field-input::placeholder {
		color: var(--text-muted);
	}

	.field-input:hover {
		border-color: var(--border-strong);
	}

	.field-input:focus-visible {
		outline: none;
		border-color: var(--accent);
		box-shadow: var(--ring);
	}

	.field-input[aria-invalid="true"] {
		border-color: var(--danger);
	}

	.field-hint {
		margin-top: var(--space-1);
		font-size: 0.875rem;
		color: var(--text-muted);
	}

	.field-error {
		display: flex;
		align-items: center;
		gap: var(--space-1);
		margin-top: var(--space-1);
		font-size: 0.875rem;
		color: var(--danger);
	}

	/* Chip filter */
	.chip {
		display: inline-flex;
		align-items: center;
		min-height: 44px;
		padding: 0 var(--space-4);
		border: 1px solid var(--border);
		border-radius: 999px;
		background: var(--surface);
		color: var(--text-muted);
		font-family: var(--font-body);
		font-size: 0.875rem;
		font-weight: 500;
		transition:
			background-color var(--dur-fast) var(--ease),
			border-color var(--dur-fast) var(--ease),
			color var(--dur-fast) var(--ease);
	}

	.chip:hover {
		border-color: var(--border-strong);
		color: var(--text);
	}

	.chip[aria-pressed="true"] {
		background: var(--accent-soft);
		border-color: color-mix(in srgb, var(--accent) 45%, transparent);
		color: var(--text);
	}

	/* Kartu alat */
	.tool-card {
		display: flex;
		flex-direction: column;
		gap: var(--space-3);
		height: 100%;
		padding: var(--space-5);
		border: 1px solid var(--border);
		border-radius: var(--radius-lg);
		background: var(--surface);
		text-decoration: none;
		color: var(--text);
		transition:
			transform var(--dur-fast) var(--ease),
			border-color var(--dur-fast) var(--ease),
			box-shadow var(--dur-fast) var(--ease);
	}

	.tool-card:hover {
		transform: translateY(-2px);
		border-color: var(--border-strong);
		box-shadow: var(--shadow-md);
	}

	.tool-card__top {
		display: flex;
		align-items: flex-start;
		justify-content: space-between;
		gap: var(--space-3);
	}

	.tool-tile {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		width: 40px;
		height: 40px;
		border-radius: var(--radius-md);
		background: color-mix(in srgb, var(--cat) 12%, transparent);
		color: var(--cat);
	}

	.category-label {
		font-family: var(--font-mono);
		font-size: 0.75rem;
		font-weight: 500;
		letter-spacing: 0.06em;
		text-transform: uppercase;
		color: var(--text-muted);
	}

	.tool-card__name {
		font-size: 1.125rem;
		font-weight: 600;
		line-height: 1.55;
	}

	.tool-card__desc {
		font-size: 0.875rem;
		line-height: 1.6;
		color: var(--text-muted);
	}

	.tool-card__foot {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		justify-content: space-between;
		gap: var(--space-2);
		margin-top: auto;
		padding-top: var(--space-1);
	}

	.privacy-label {
		display: inline-flex;
		align-items: center;
		gap: var(--space-1);
		font-size: 0.8125rem;
		color: var(--text-muted);
	}

	.status-label {
		font-family: var(--font-mono);
		font-size: 0.6875rem;
		letter-spacing: 0.06em;
		text-transform: uppercase;
		color: var(--text-muted);
	}

	/* Beranda */
	.hero {
		padding-top: var(--space-7);
		padding-bottom: var(--space-6);
		border-bottom: 1px solid var(--border);
	}

	.hero__title {
		max-width: 18ch;
		font-size: 2.125rem;
		font-weight: 800;
		letter-spacing: -0.02em;
	}

	.hero__lede {
		max-width: 56ch;
		margin-top: var(--space-3);
		font-size: 1rem;
		color: var(--text-muted);
	}

	.hero__search {
		position: relative;
		max-width: 520px;
		margin-top: var(--space-5);
	}

	.hero__search-icon {
		position: absolute;
		left: var(--space-3);
		top: 50%;
		transform: translateY(-50%);
		color: var(--text-muted);
		pointer-events: none;
	}

	.hero__search .field-input {
		padding-left: calc(var(--space-3) + 28px);
	}

	.status-note {
		display: flex;
		gap: var(--space-2);
		max-width: 56ch;
		margin-top: var(--space-3);
		font-size: 0.875rem;
		color: var(--text-muted);
	}

	.status-note strong {
		color: var(--text);
		font-weight: 600;
	}

	.catalog {
		padding-top: var(--space-6);
		padding-bottom: var(--space-7);
	}

	.section-head {
		display: flex;
		flex-wrap: wrap;
		align-items: baseline;
		justify-content: space-between;
		gap: var(--space-2);
	}

	.section-title {
		font-size: 1.5rem;
		font-weight: 700;
	}

	.section-meta {
		font-family: var(--font-mono);
		font-size: 0.75rem;
		letter-spacing: 0.06em;
		text-transform: uppercase;
		color: var(--text-muted);
	}

	.chip-row {
		display: flex;
		flex-wrap: wrap;
		gap: var(--space-2);
		margin-top: var(--space-4);
	}

	.tool-grid {
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		gap: var(--space-4);
		margin: var(--space-5) 0 0;
		padding: 0;
		list-style: none;
	}

	@media (min-width: 768px) {
		.tool-grid {
			grid-template-columns: repeat(2, minmax(0, 1fr));
		}
	}

	@media (min-width: 1024px) {
		.tool-grid {
			grid-template-columns: repeat(3, minmax(0, 1fr));
		}
	}

	@media (min-width: 1280px) {
		.tool-grid {
			grid-template-columns: repeat(4, minmax(0, 1fr));
		}
		.hero {
			padding-top: var(--space-9);
		}
		.hero__title {
			font-size: 3rem;
			line-height: 1.15;
		}
		.catalog {
			padding-top: var(--space-7);
			padding-bottom: var(--space-9);
		}
	}

	.empty-state {
		margin-top: var(--space-5);
		padding: var(--space-6) var(--space-5);
		border: 1px dashed var(--border-strong);
		border-radius: var(--radius-lg);
		background: var(--surface);
		text-align: center;
	}

	.empty-state__title {
		font-size: 1rem;
		font-weight: 600;
	}

	.empty-state__body {
		max-width: 46ch;
		margin: var(--space-2) auto 0;
		font-size: 0.875rem;
		color: var(--text-muted);
	}

	/* Bagian prinsip */
	.principles {
		padding-block: var(--space-7);
		background: var(--surface-2);
		border-block: 1px solid var(--border);
	}

	.principles__grid {
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		gap: var(--space-5);
		margin-top: var(--space-5);
	}

	.principle__title {
		font-size: 1rem;
		font-weight: 600;
	}

	.principle__body {
		margin-top: var(--space-1);
		font-size: 0.875rem;
		color: var(--text-muted);
	}

	@media (min-width: 768px) {
		.principles__grid {
			grid-template-columns: repeat(3, minmax(0, 1fr));
			gap: var(--space-6);
		}
	}

	/* Footer */
	.site-footer {
		padding-block: var(--space-6) var(--space-7);
		border-top: 1px solid var(--border);
	}

	.footer-inner {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		justify-content: space-between;
		gap: var(--space-4);
	}

	.footer-links {
		display: flex;
		flex-wrap: wrap;
		gap: var(--space-4);
		margin: 0;
		padding: 0;
		list-style: none;
		font-size: 0.875rem;
	}

	.footer-links a {
		display: inline-flex;
		align-items: center;
		min-height: 44px;
		color: var(--text-muted);
		text-decoration: none;
	}

	.footer-links a:hover {
		color: var(--text);
		text-decoration: underline;
	}

	.footer-note {
		width: 100%;
		font-size: 0.8125rem;
		color: var(--text-muted);
	}

	/* Halaman alat */
	.breadcrumb {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		gap: var(--space-2);
		padding-top: var(--space-5);
		font-size: 0.875rem;
		color: var(--text-muted);
	}

	.breadcrumb a {
		display: inline-flex;
		align-items: center;
		min-height: 44px;
		text-decoration: none;
	}

	.breadcrumb a:hover {
		text-decoration: underline;
	}

	.tool-head {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		gap: var(--space-3);
		margin-top: var(--space-2);
	}

	.tool-title {
		font-size: 1.625rem;
		font-weight: 700;
	}

	.tool-lede {
		max-width: 60ch;
		margin-top: var(--space-2);
		color: var(--text-muted);
	}

	.tool-body {
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		gap: var(--space-4);
		margin-top: var(--space-5);
		padding-bottom: var(--space-7);
	}

	.workspace {
		min-height: 280px;
		padding: var(--space-6) var(--space-5);
		border: 1px solid var(--border);
		border-radius: var(--radius-lg);
		background: var(--surface);
		display: flex;
		flex-direction: column;
		align-items: center;
		justify-content: center;
		gap: var(--space-3);
		text-align: center;
	}

	.panel {
		padding: var(--space-5);
		border: 1px solid var(--border);
		border-radius: var(--radius-lg);
		background: var(--surface);
	}

	.panel__title {
		font-size: 1rem;
		font-weight: 600;
	}

	.plan-list {
		margin: var(--space-3) 0 0;
		padding: 0;
		list-style: none;
		display: grid;
		gap: var(--space-3);
	}

	.plan-list li {
		display: grid;
		gap: 2px;
		padding-bottom: var(--space-3);
		border-bottom: 1px solid var(--border);
		font-size: 0.875rem;
	}

	.plan-list li:last-child {
		padding-bottom: 0;
		border-bottom: 0;
	}

	.plan-list span:first-child {
		color: var(--text);
	}

	.plan-list span:last-child {
		font-family: var(--font-mono);
		font-size: 0.6875rem;
		letter-spacing: 0.06em;
		text-transform: uppercase;
		color: var(--text-muted);
	}

	.related {
		padding-block: var(--space-6);
		border-top: 1px solid var(--border);
	}

	.related__grid {
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		gap: var(--space-4);
		margin-top: var(--space-4);
	}

	@media (min-width: 768px) {
		.related__grid {
			grid-template-columns: repeat(3, minmax(0, 1fr));
		}
	}

	@media (min-width: 1024px) {
		.tool-body {
			grid-template-columns: minmax(0, 1fr) 340px;
			align-items: start;
		}
	}

	/* Modal dan palet */
	.modal {
		width: min(640px, calc(100vw - var(--space-6)));
		max-height: calc(100dvh - var(--space-7));
		margin: auto;
		padding: 0;
		border: 1px solid var(--border);
		border-radius: var(--radius-xl);
		background: var(--surface);
		color: var(--text);
		box-shadow: var(--shadow-lg);
		overflow: hidden;
	}

	.modal::backdrop {
		background: rgba(0, 0, 0, 0.5);
	}

	.palette__head {
		display: flex;
		align-items: center;
		gap: var(--space-2);
		padding: var(--space-3) var(--space-4);
		border-bottom: 1px solid var(--border);
	}

	.palette__input {
		flex: 1;
		min-height: 44px;
		border: 0;
		background: transparent;
		color: var(--text);
		font-family: var(--font-body);
		font-size: 1rem;
	}

	.palette__input:focus-visible {
		outline: none;
	}

	.palette__list {
		margin: 0;
		padding: var(--space-2);
		list-style: none;
		max-height: min(60vh, 420px);
		overflow-y: auto;
	}

	.palette__link {
		display: flex;
		align-items: center;
		gap: var(--space-3);
		min-height: 48px;
		padding: var(--space-2) var(--space-3);
		border-radius: var(--radius-md);
		text-decoration: none;
		color: var(--text);
	}

	.palette__link:hover,
	.palette__link:focus-visible {
		background: var(--surface-2);
	}

	.palette__name {
		font-weight: 500;
	}

	.palette__cat {
		margin-left: auto;
		font-family: var(--font-mono);
		font-size: 0.6875rem;
		letter-spacing: 0.06em;
		text-transform: uppercase;
		color: var(--text-muted);
	}

	.palette__empty {
		padding: var(--space-6) var(--space-4);
		text-align: center;
		font-size: 0.875rem;
		color: var(--text-muted);
	}

	.palette__foot {
		display: flex;
		gap: var(--space-4);
		padding: var(--space-2) var(--space-4) var(--space-3);
		border-top: 1px solid var(--border);
		font-size: 0.75rem;
		color: var(--text-muted);
	}

	/* Toast dan progress */
	.toast-region {
		position: fixed;
		right: var(--space-4);
		bottom: var(--space-4);
		z-index: 60;
		display: flex;
		flex-direction: column;
		gap: var(--space-2);
		max-width: 360px;
	}

	.toast {
		display: flex;
		align-items: center;
		gap: var(--space-3);
		padding: var(--space-3) var(--space-4);
		border: 1px solid var(--border-strong);
		border-radius: var(--radius-md);
		background: var(--surface);
		box-shadow: var(--shadow-md);
		font-size: 0.875rem;
	}

	.toast__action {
		margin-left: auto;
		border: 0;
		background: none;
		color: var(--accent);
		font-weight: 600;
		min-height: 44px;
		padding: 0 var(--space-2);
	}

	.progress {
		height: 6px;
		border-radius: 999px;
		background: var(--surface-2);
		overflow: hidden;
	}

	.progress__bar {
		height: 100%;
		border-radius: inherit;
		background: var(--accent);
		transition: width var(--dur-base) var(--ease);
	}

	/* Tabs */
	.tabs {
		display: flex;
		gap: var(--space-1);
		border-bottom: 1px solid var(--border);
	}

	.tab {
		min-height: 44px;
		padding: 0 var(--space-3);
		margin-bottom: -1px;
		border: 0;
		border-bottom: 2px solid transparent;
		background: none;
		color: var(--text-muted);
		font-family: var(--font-display);
		font-size: 0.875rem;
		font-weight: 500;
	}

	.tab[aria-selected="true"] {
		color: var(--text);
		border-bottom-color: var(--accent);
	}

	/* Dropzone */
	.dropzone {
		display: flex;
		flex-direction: column;
		align-items: center;
		gap: var(--space-3);
		padding: var(--space-6) var(--space-5);
		border: 2px dashed var(--border-strong);
		border-radius: var(--radius-lg);
		background: var(--surface);
		text-align: center;
		transition:
			border-color var(--dur-fast) var(--ease),
			background-color var(--dur-fast) var(--ease);
	}

	.dropzone[data-dragover="true"] {
		border-color: var(--accent);
		background: var(--accent-soft);
	}

	.sr-only {
		position: absolute;
		width: 1px;
		height: 1px;
		padding: 0;
		margin: -1px;
		overflow: hidden;
		clip-path: inset(50%);
		white-space: nowrap;
		border: 0;
	}

	/* Halaman teks */
	.prose-page {
		max-width: 68ch;
		padding-block: var(--space-7) var(--space-9);
	}

	.prose-page h1 {
		font-size: 2rem;
		font-weight: 800;
	}

	.prose-page h2 {
		margin-top: var(--space-6);
		font-size: 1.25rem;
		font-weight: 700;
	}

	.prose-page p,
	.prose-page ul {
		margin-top: var(--space-3);
		color: var(--text-muted);
	}

	.prose-page li {
		margin-top: var(--space-1);
	}

	.prose-page a {
		color: var(--text);
	}
}

content.text:
Now the tool types and meta files.

src/lib/tool-types.ts:

```ts
export type ToolCategory = 'gambar' | 'diagram' | 'dokumen' | 'foto' | 'berbagi' | 'generator';
export type ToolStatus = 'rencana' | 'siap';
export type PrivacyMode = 'lokal' | 'server';
export type ToolIcon = 'pencil' | 'network' | 'file-text' | 'user-round' | 'link' | 'braces';

export interface ToolPlan { label: string; requirement: string }

export interface ToolMeta {
  slug: string;
  name: string;
  category: ToolCategory;
  tagline: string;
  keywords: string[];
  privacy: PrivacyMode;
  status: ToolStatus;
  icon: ToolIcon;
  plans: ToolPlan[];
}
```

Do I need requirement IDs displayed? Showing "FR-PDF-01" is developer-facing noise. Instead store plans as strings and show label + status "Rencana". Simpler: plans: string[]. But traceability to PRD is nice in code comments? No comments. Keep plans: string[] and mention PRD source in the panel footnote "Dari PRD v1.0, modul ..." — real.

Let me keep plans: string[].

Categories:
```ts
export const categories: { id: ToolCategory; label: string }[] = [
  { id: 'gambar', label: 'Gambar' }, ...
];
export const privacyLabel: Record<PrivacyMode, string> = { lokal: 'Di perangkatmu', server: 'Lewat server' };
export const statusLabel: Record<ToolStatus, string> = { rencana: 'Belum jadi', siap: 'Siap' };
```
design says badge "Pakai server". Use 'Pakai server' for accuracy.

Now meta files.

draw: name 'Kanvas Gambar', tagline 'Sketsa, tulisan, dan diagram bebas di kanvas, lalu ekspor ke PNG, SVG, atau file .excalidraw.' Hmm .excalidraw is brand file format; fine, it's a format name, not a trademark claim. Maybe avoid: 'ekspor ke PNG atau SVG'. Keep simpler.

Let me write concise, no em dash, casual tone, no buzzwords.

draw:
- name: 'Kanvas Gambar'
- tagline: 'Gambar bebas, tulis catatan, dan susun sketsa di kanvas. Hasilnya bisa diekspor jadi PNG atau SVG.'
- keywords: ['draw','gambar','sketsa','coret','tulis','kanvas','excalidraw','diagram bebas']
- plans: ['Kanvas dengan bentuk, panah, teks, pensil, dan penghapus','Simpan otomatis di browser, pulih saat dibuka lagi','Ekspor PNG dan SVG, impor file Excalidraw']

diagram:
