import type { IconName } from './icons';

export type ToolCategory =
	| 'gambar'
	| 'diagram'
	| 'dokumen'
	| 'foto'
	| 'berbagi'
	| 'generator';

export type ToolStatus = 'rencana' | 'siap';
export type PrivacyMode = 'lokal' | 'server';

export interface ToolMeta {
	slug: string;
	name: string;
	category: ToolCategory;
	tagline: string;
	keywords: string[];
	privacy: PrivacyMode;
	status: ToolStatus;
	icon: IconName;
	plans: string[];
}

export const categories: { id: ToolCategory; label: string }[] = [
	{ id: 'gambar', label: 'Gambar' },
	{ id: 'diagram', label: 'Diagram' },
	{ id: 'dokumen', label: 'Dokumen' },
	{ id: 'foto', label: 'Foto' },
	{ id: 'berbagi', label: 'Berbagi' },
	{ id: 'generator', label: 'Generator' },
];

export const privacyLabel: Record<PrivacyMode, string> = {
	lokal: 'Di perangkatmu',
	server: 'Pakai server',
};

export const privacyNote: Record<PrivacyMode, string> = {
	lokal: 'File diproses di browser, tidak diunggah ke server.',
	server:
		'File diunggah ke penyimpanan sementara, lalu dihapus otomatis saat link kedaluwarsa.',
};

export const statusLabel: Record<ToolStatus, string> = {
	rencana: 'Belum jadi',
	siap: 'Siap dipakai',
};

export function categoryLabel(category: ToolCategory): string {
	return categories.find((item) => item.id === category)?.label ?? category;
}

import type { ToolMeta } from './tool-types';

export function normalize(value: string): string {
	return value
		.toLowerCase()
		.normalize('NFD')
		.replace(/[\u0300-\u036f]/g, '')
		.trim();
}

export function matches(haystack: string[], query: string): boolean {
	const words = normalize(query).split(/\s+/).filter(Boolean);
	if (words.length === 0) return true;
	const fields = haystack.map(normalize);
	return words.every((word) => fields.some((field) => field.includes(word)));
}

export function searchableFields(tool: ToolMeta): string[] {
	return [tool.name, tool.category, tool.tagline, ...tool.keywords];
}

import type { ToolMeta } from './tool-types';
import { categories } from './tool-types';

const modules = import.meta.glob<{ meta: ToolMeta }>('../features/*/meta.ts', {
	eager: true,
});

const categoryOrder = new Map(categories.map((item, index) => [item.id, index]));

export const tools: ToolMeta[] = Object.values(modules)
	.map((module) => module.meta)
	.sort((a, b) => {
		const byCategory =
			(categoryOrder.get(a.category) ?? 99) - (categoryOrder.get(b.category) ?? 99);
		return byCategory !== 0 ? byCategory : a.name.localeCompare(b.name, 'id');
	});

export function getTool(slug: string): ToolMeta | undefined {
	return tools.find((tool) => tool.slug === slug);
}

export function relatedTools(tool: ToolMeta, count = 3): ToolMeta[] {
	const sameCategory = tools.filter(
		(item) => item.slug !== tool.slug && item.category === tool.category,
	);
	const others = tools.filter(
		(item) => item.slug !== tool.slug && item.category !== tool.category,
	);
	return [...sameCategory, ...others].slice(0, count);
}

