}

const { label, items } = Astro.props;
const first = items[0]?.id;
---

<div class="tabs" role="tablist" aria-label={label}>
	{
		items.map((item) => (
			<button
				type="button"
				class="tab"
				role="tab"
				id={`tab-${item.id}`}
				aria-controls={`panel-${item.id}`}
				aria-selected={item.id === first ? 'true' : 'false'}
				tabindex={item.id === first ? 0 : -1}
				data-tab={item.id}
			>
				{item.label}
			</button>
		))
	}
</div>
<div data-tab-panels>
	<slot />
</div>

<script>
	type Tab = HTMLButtonElement;

	const groups = document.querySelectorAll<HTMLElement>('[role="tablist"]');

	groups.forEach((list) => {
		const menu: Tab[] = Array.from(list.querySelectorAll<Tab>('[role="tab"]'));
		const wrapper = list.nextElementSibling as HTMLElement | null;
		if (!wrapper || menu.length === 0) return;

		const panels = Array.from(
			wrapper.querySelectorAll<HTMLElement>('[data-panel]'),
		);

		const select = (id: string, focus = false) => {
			menu.forEach((tab) => {
				const active = tab.dataset.tab === id;
				tab.setAttribute('aria-selected', active ? 'true' : 'false');
				tab.tabIndex = active ? 0 : -1;
				if (active && focus) tab.focus();
			});
			panels.forEach((panel) => {
				panel.hidden = panel.dataset.panel !== id;
			});
		};

		const firstId = menu[0]?.dataset.tab;
		if (firstId) select(firstId);

		list.addEventListener('click', (event) => {
			const tab = (event.target as HTMLElement).closest<Tab>('[role="tab"]');
			if (tab?.dataset.tab) select(tab.dataset.tab);
		});

		list.addEventListener('keydown', (event) => {
			const current = menu.findIndex((tab) => tab === document.activeElement);
			if (current === -1) return;

			if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
				event.preventDefault();
				const step = event.key === 'ArrowRight' ? 1 : -1;
				const next = (current + step + menu.length) % menu.length;
				const nextTab = menu[next];
				if (nextTab?.dataset.tab) select(nextTab.dataset.tab, true);
			}

			if (event.key === 'Home') {
				event.preventDefault();
				const firstTab = menu[0];
				if (firstTab?.dataset.tab) select(firstTab.dataset.tab, true);
			}

			if (event.key === 'End') {
				event.preventDefault();
				const lastTab = menu[menu.length - 1];
				if (lastTab?.dataset.tab) select(lastTab.dataset.tab, true);
			}
		});
	});
</script>

