(() => {
  const parse = (c) => (c.match(/[\d.]+/g) || []).slice(0, 3).map(Number);
  const lum = (c) => parse(c).map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((acc, v, i) => acc + v * [0.2126, 0.7152, 0.0722][i], 0);
  const ratio = (fg, bg) => { const a = lum(fg), b = lum(bg); const hi = Math.max(a, b), lo = Math.min(a, b); return Number(((hi + 0.05) / (lo + 0.05)).toFixed(2)); };
  const bgOf = (el) => { let node = el; while (node) { const bg = getComputedStyle(node).backgroundColor; if (bg && !bg.includes('rgba(0, 0, 0, 0)') && bg !== 'transparent') return bg; node = node.parentElement; } return 'rgb(255,255,255)'; };
  const targets = ['h1', '.hero__lede', '.status-note', '.section-meta', '.catalog-intro', '.tool-card__desc', '.category-label', '.status-label', '.privacy-label', '.chip:not([aria-pressed="true"])', '.field-hint', '.footer-note', '.footer-links a', '#catalog-search'];
  const out = [];
  targets.forEach((sel) => {
    const el = document.querySelector(sel);
    if (!el) { out.push({ sel, missing: true }); return; }
    const cs = getComputedStyle(el);
    const color = sel === '#catalog-search' ? getComputedStyle(el, '::placeholder').color : cs.color;
    out.push({ sel, ratio: ratio(color, bgOf(el)), size: cs.fontSize, weight: cs.fontWeight });
  });
