`RendererOutput` may be `string | false`. Fine.

Now write the lib files.

First `src/lib/json-tools.ts`.

Let me write carefully.

```ts
export type JsonError = {
	message: string;
	index: number;
	line: number;
	column: number;
};

export type JsonParseResult =
	| { ok: true; data: unknown }
	| { ok: false; error: JsonError };

export type JsonTextResult =
	| { ok: true; text: string }
	| { ok: false; error: JsonError };
```

Parser:

```ts
class JsonReader {
	text: string;
	i = 0;
	constructor(text: string) { this.text = text; }

	fail(message: string): never { throw new JsonParseError(message, this.i); }

	skip() {
		const text = this.text;
		while (this.i < text.length) {
			const c = text[this.i];
			if (c === ' ' || c === '\n' || c === '\r' || c === '\t') this.i += 1;
			else break;
		}
	}

	parseDocument(): unknown {
		this.skip();
		if (this.i >= this.text.length) {
			// Point at the first non-space char... empty document
			this.fail('Dokumen masih kosong.');
		}
		const value = this.parseValue();
		this.skip();
		if (this.i < this.text.length) {
			this.fail(`Karakter "${this.text[this.i]}" tidak terduga setelah nilai.`);
		}
		return value;
	}

	parseValue(): unknown {
		this.skip();
		const c = this.text[this.i];
		if (c === undefined) this.fail('Nilai belum selesai.');
		if (c === '{') return this.parseObject();
		if (c === '[') return this.parseArray();
		if (c === '"') return this.parseString();
		if (c === '-' || (c >= '0' && c <= '9')) return this.parseNumber();
		if (this.text.startsWith('true', this.i)) { this.i += 4; return true; }
		if (this.text.startsWith('false', this.i)) { this.i += 5; return false; }
		if (this.text.startsWith('null', this.i)) { this.i += 4; return null; }
		this.fail(`Karakter "${c}" bukan awal nilai JSON yang sah.`);
	}
```

Note `parseValue` returns unknown; `this.fail` typed never so TS ok.

parseObject:
```ts
parseObject(): Record<string, unknown> {
	this.i += 1; // {
	const result: Record<string, unknown> = {};
	this.skip();
	if (this.text[this.i] === '}') { this.i += 1; return result; }
	while (true) {
		this.skip();
		if (this.text[this.i] !== '"') this.fail('Nama properti harus diapit tanda kutip.');
		const key = this.parseString();
		this.skip();
		if (this.text[this.i] !== ':') this.fail('Tanda titik dua : belum ada setelah nama properti.');
		this.i += 1;
		result[key] = this.parseValue();
		this.skip();
		const c = this.text[this.i];
		if (c === ',') { this.i += 1; continue; }
		if (c === '}') { this.i += 1; return result; }
		if (c === undefined) this.fail('Kurung kurawal } belum ditutup.');
		this.fail(`Koma atau } dibutuhkan, bukan "${c}".`);
	}
}
```
Trailing comma case: after comma, loop skip, next char '}' not '"' → "Nama properti harus diapit tanda kutip." At index of '}'. Message could be better: "Koma berlebih sebelum }". Handle: after comma, if next is `}` → fail('Koma berlebih sebelum }.'). Let me add that in the loop start:
```ts
if (this.i > 0 && this.text[this.i] === '}') this.fail('Koma berlebih sebelum }.');
```
Careful: only when we've just consumed a comma. Restructure: after consuming comma, `this.skip(); if (this.text[this.i] === '}') this.fail('Koma berlebih sebelum }.'); continue;`

Same for arrays.

parseArray: similar. Items can be any value; trailing comma check.

parseString:
```ts
parseString(): string {
	this.i += 1; // opening quote
	let out = '';
	const text = this.text;
	while (true) {
		const c = text[this.i];
		if (c === undefined) this.fail('Tanda kutip penutup belum ada.');
		if (c === '"') { this.i += 1; return out; }
		if (c === '\\') {
			this.i += 1;
			const esc = text[this.i];
			if (esc === undefined) this.fail('Escape belum selesai.');
			if (esc === '"' || esc === '\\' || esc === '/') { out += esc; this.i += 1; continue; }
			if (esc === 'b') { out += '\b'; this.i += 1; continue; }
			... f,n,r,t
