export function highlightJson(text: string): string {
	let out = '';
	let i = 0;
	while (i < text.length) {
		const c = text[i]!;
		if (c === '"') {
			const start = i;
			i += 1;
			while (i < text.length) {
				if (text[i] === '\\') { i += 2; continue; }
				if (text[i] === '"') { i += 1; break; }
				i += 1;
			}
			const raw = text.slice(start, i);
			let j = i;
			while (j < text.length && /\s/.test(text[j]!)) j += 1;
			const isKey = text[j] === ':';
			out += `<span class="${isKey ? 'tok-key' : 'tok-string'}">${escapeHtml(raw)}</span>`;
			continue;
		}
		if (c === '-' || (c >= '0' && c <= '9')) {
			const start = i;
			i += 1;
			while (i < text.length && /[-+.eE0-9]/.test(text[i]!)) i += 1;
			out += `<span class="tok-number">${escapeHtml(text.slice(start, i))}</span>`;
			continue;
		}
		if (text.startsWith('true', i) || text.startsWith('false', i) || text.startsWith('null', i)) {
			const word = text.startsWith('true', i) ? 'true' : text.startsWith('false', i) ? 'false' : 'null';
			out += `<span class="tok-literal">${word}</span>`;
			i += word.length;
			continue;
		}
		out += escapeHtml(c);
		i += 1;
	}
	return out;
}
```
