```ts
function renderValue(value: unknown, key: string | null, depth: number, openDepth: number): string {
	const keyPart = key === null ? '' : `<span class="tok-key">${escapeHtml(key)}</span><span class="tok-punct">: </span>`;
	if (!isContainer(value)) return `<li>${keyPart}${renderPrimitive(value)}</li>`;
	if (Array.isArray(value) && value.length === 0) return `<li>${keyPart}<span class="tok-punct">[]</span></li>`;
	if (!Array.isArray(value) && Object.keys(value).length === 0) return `<li>${keyPart}<span class="tok-punct">{}</span></li>`;
	const entries = Array.isArray(value)
		? value.map((item, index) => [String(index), item] as const)
		: Object.entries(value as Record<string, unknown>);
	const children = entries.map(([childKey, child]) => renderValue(child, childKey, depth + 1, openDepth)).join('');
	const open = depth < openDepth ? ' open' : '';
	return `<li><details${open}><summary>${keyPart}<span class="json-tree__count">${containerLabel(value)}</span></summary><ul>${children}</ul></details></li>`;
}

function renderPrimitive(value: unknown): string {
	if (typeof value === 'string') return `<span class="tok-string">"${escapeHtml(value)}"</span>`;
	if (typeof value === 'number') return `<span class="tok-number">${String(value)}</span>`;
	if (typeof value === 'boolean') return `<span class="tok-literal">${String(value)}</span>`;
	return `<span class="tok-literal">null</span>`;
}
```
