const BADGES: Record<ReadmeLicense, { image: string; link: string }> = {
	MIT: { image: 'https://img.shields.io/badge/License-MIT-yellow.svg', link: 'https://opensource.org/licenses/MIT' },
	'Apache-2.0': { image: 'https://img.shields.io/badge/License-Apache%202.0-blue.svg', link: 'https://www.apache.org/licenses/LICENSE-2.0' },
	'GPL-3.0': { image: 'https://img.shields.io/badge/License-GPLv3-blue.svg', link: 'https://www.gnu.org/licenses/gpl-3.0.html' },
};

export function generateReadme(input: ReadmeInput): string {
	const name = input.name.trim();
	if (name === '') return '';
	const parts: string[] = [`# ${name}`];
	if (input.description.trim()) parts.push(input.description.trim());
	if (input.showLicenseBadge && input.license) {
		const badge = BADGES[input.license];
		parts.push(`[![Lisensi: ${input.license}](${badge.image})](${badge.link})`);
	}
	const features = lines(input.features);
	if (features.length) parts.push('## Fitur\n\n' + bulletList(features));
	const install = lines(input.install);
	if (install.length) parts.push('## Instalasi\n\n```bash\n' + install.join('\n') + '\n```');
	const usage = input.usage.trim();
	if (usage) parts.push('## Cara pakai\n\n' + usage);
	if (input.license) parts.push('## Lisensi\n\n' + input.license);
	return parts.join('\n\n') + '\n';
}
