const entities: Record<string, string> = {
	'&': '&amp;',
	'<': '&lt;',
	'>': '&gt;',
	'"': '&quot;',
	"'": '&#39;',
};

export function escapeHtml(value: string): string {
	return value.replace(/[&<>"']/g, (char) => entities[char] ?? char);
}

import { escapeHtml } from './html';

export interface JsonPosition {
	index: number;
	line: number;
	column: number;
}

export interface JsonError extends JsonPosition {
	message: string;
}

export type JsonParseResult =
	| { ok: true; data: unknown }
	| { ok: false; error: JsonError };

export type JsonTextResult =
	| { ok: true; text: string; data: unknown }
	| { ok: false; error: JsonError };

class JsonSyntaxError extends Error {
	index: number;

	constructor(message: string, index: number) {
		super(message);
		this.index = index;
	}
}

function isDigit(char: string | undefined): boolean {
	return char !== undefined && char >= '0' && char <= '9';
}

class JsonReader {
	text: string;
	index = 0;

	constructor(text: string) {
		this.text = text;
	}

	fail(message: string): never {
		throw new JsonSyntaxError(message, this.index);
	}

	skipWhitespace(): void {
		while (this.index < this.text.length) {
			const char = this.text[this.index];
			if (char === ' ' || char === '\n' || char === '\r' || char === '\t') {
				this.index += 1;
			} else {
				break;
			}
		}
	}

	parseDocument(): unknown {
		this.skipWhitespace();
		if (this.index >= this.text.length) {
			this.fail('Dokumen masih kosong.');
		}
		const value = this.parseValue();
		this.skipWhitespace();
		if (this.index < this.text.length) {
			this.fail(`Karakter "${this.text[this.index]}" tidak terduga setelah nilai.`);
		}
		return value;
	}

	parseValue(): unknown {
		this.skipWhitespace();
		const char = this.text[this.index];
		if (char === undefined) {
			this.fail('Nilai belum selesai.');
		}
		if (char === '{') return this.parseObject();
		if (char === '[') return this.parseArray();
		if (char === '"') return this.parseString();
		if (char === '-' || isDigit(char)) return this.parseNumber();
		if (this.text.startsWith('true', this.index)) {
			this.index += 4;
			return true;
		}
		if (this.text.startsWith('false', this.index)) {
			this.index += 5;
			return false;
		}
		if (this.text.startsWith('null', this.index)) {
			this.index += 4;
			return null;
		}
		this.fail(`Karakter "${char}" bukan awal nilai JSON yang sah.`);
	}

	parseObject(): Record<string, unknown> {
		this.index += 1;
		const result: Record<string, unknown> = {};
		this.skipWhitespace();
		if (this.text[this.index] === '}') {
			this.index += 1;
			return result;
		}

		while (true) {
			this.skipWhitespace();
			if (this.text[this.index] === '}') {
				this.fail('Koma berlebih sebelum }.');
			}
			if (this.text[this.index] !== '"') {
				this.fail('Nama properti harus diapit tanda kutip.');
			}
			const key = this.parseString();
			this.skipWhitespace();
			if (this.text[this.index] !== ':') {
				this.fail('Tanda titik dua : belum ada setelah nama properti.');
			}
			this.index += 1;
			result[key] = this.parseValue();
			this.skipWhitespace();
			const char = this.text[this.index];
			if (char === ',') {
				this.index += 1;
				continue;
			}
			if (char === '}') {
				this.index += 1;
				return result;
			}
			if (char === undefined) {
				this.fail('Kurung kurawal } belum ditutup.');
			}
			this.fail(`Koma atau } dibutuhkan, bukan "${char}".`);
		}
	}

	parseArray(): unknown[] {
		this.index += 1;
		const result: unknown[] = [];
		this.skipWhitespace();
		if (this.text[this.index] === ']') {
			this.index += 1;
			return result;
		}

		while (true) {
			this.skipWhitespace();
			if (this.text[this.index] === ']') {
				this.fail('Koma berlebih sebelum ].');
			}
			result.push(this.parseValue());
			this.skipWhitespace();
			const char = this.text[this.index];
			if (char === ',') {
				this.index += 1;
				continue;
			}
			if (char === ']') {
				this.index += 1;
				return result;
			}
			if (char === undefined) {
				this.fail('Kurung siku ] belum ditutup.');
			}
			this.fail(`Koma atau ] dibutuhkan, bukan "${char}".`);
		}
	}

	parseString(): string {
		this.index += 1;
		let result = '';

		while (true) {
			const char = this.text[this.index];
			if (char === undefined) {
				this.fail('Tanda kutip penutup belum ada.');
			}
			if (char === '"') {
				this.index += 1;
				return result;
			}
			if (char === '\\') {
				this.index += 1;
				const escape = this.text[this.index];
				if (escape === undefined) {
					this.fail('Escape belum selesai.');
				}
				if (escape === '"' || escape === '\\' || escape === '/') {
					result += escape;
					this.index += 1;
					continue;
				}
				const simple: Record<string, string> = {
					b: '\b',
					f: '\f',
					n: '\n',
					r: '\r',
					t: '\t',
				};
				if (simple[escape] !== undefined) {
					result += simple[escape];
					this.index += 1;
					continue;
				}
				if (escape === 'u') {
					const hex = this.text.slice(this.index + 1, this.index + 5);
					if (hex.length !== 4 || /[^0-9a-fA-F]/.test(hex)) {
						this.index += 1;
						this.fail('Kode \\u harus diikuti empat digit heksadesimal.');
					}
					result += String.fromCharCode(parseInt(hex, 16));
					this.index += 5;
					continue;
				}
				this.index += 1;
				this.fail(`Escape \\${escape} tidak dikenal.`);
			}
			const code = char.charCodeAt(0);
			if (code < 0x20) {
				this.fail('Karakter kontrol tidak boleh langsung di dalam string.');
			}
			result += char;
			this.index += 1;
		}
	}

	parseNumber(): number {
		const start = this.index;
		const text = this.text;

		if (text[this.index] === '-') this.index += 1;

		if (text[this.index] === '0') {
			this.index += 1;
		} else if (text[this.index] !== undefined && text[this.index] >= '1' && text[this.index] <= '9') {
			this.index += 1;
			while (isDigit(text[this.index])) this.index += 1;
		} else {
			this.fail('Angka tidak valid.');
		}

		if (text[this.index] === '.') {
			this.index += 1;
			if (!isDigit(text[this.index])) {
				this.fail('Angka desimal butuh digit setelah titik.');
			}
			while (isDigit(text[this.index])) this.index += 1;
		}

		const exponent = text[this.index];
		if (exponent === 'e' || exponent === 'E') {
			this.index += 1;
			const sign = text[this.index];
			if (sign === '+' || sign === '-') this.index += 1;
			if (!isDigit(text[this.index])) {
				this.fail('Eksponen butuh digit.');
			}
			while (isDigit(text[this.index])) this.index += 1;
		}

		return Number(text.slice(start, this.index));
	}
}

export function lineColumnAt(input: string, index: number): { line: number; column: number } {
	const safe = Math.max(0, Math.min(index, input.length));
	const before = input.slice(0, safe);
	const line = before.split('\n').length;
	const lastBreak = before.lastIndexOf('\n');
	return { line, column: safe - lastBreak };
}

export function parseJson(input: string): JsonParseResult {
	try {
		return { ok: true, data: new JsonReader(input).parseDocument() };
	} catch (error) {
		if (error instanceof JsonSyntaxError) {
			return {
				ok: false,
				error: {
					message: error.message,
					index: error.index,
					...lineColumnAt(input, error.index),
				},
			};
		}
		if (error instanceof RangeError) {
			return {
				ok: false,
				error: {
					message: 'Struktur JSON terlalu dalam untuk dibaca.',
					index: 0,
					...lineColumnAt(input, 0),
				},
			};
		}
		throw error;
	}
}

export function formatJson(input: string): JsonTextResult {
	const parsed = parseJson(input);
	if (!parsed.ok) return parsed;
	return { ok: true, text: JSON.stringify(parsed.data, null, 2), data: parsed.data };
}

export function minifyJson(input: string): JsonTextResult {
	const parsed = parseJson(input);
	if (!parsed.ok) return parsed;
	return { ok: true, text: JSON.stringify(parsed.data), data: parsed.data };
}

export function highlightJson(text: string): string {
	let html = '';
	let index = 0;

	while (index < text.length) {
		const char = text[index];

		if (char === '"') {
			const start = index;
			index += 1;
			while (index < text.length) {
				if (text[index] === '\\') {
					index += 2;
					continue;
				}
				if (text[index] === '"') {
					index += 1;
					break;
				}
				index += 1;
			}
			let ahead = index;
			while (ahead < text.length && /\s/.test(text[ahead] ?? '')) ahead += 1;
			const className = text[ahead] === ':' ? 'tok-key' : 'tok-string';
			html += `<span class="${className}">${escapeHtml(text.slice(start, index))}</span>`;
			continue;
		}

		if (char === '-' || isDigit(char)) {
			const start = index;
			index += 1;
			while (index < text.length && /[-+.eE0-9]/.test(text[index] ?? '')) index += 1;
			html += `<span class="tok-number">${escapeHtml(text.slice(start, index))}</span>`;
			continue;
		}

		const literal = text.startsWith('true', index)
			? 'true'
			: text.startsWith('false', index)
				? 'false'
				: text.startsWith('null', index)
					? 'null'
					: '';
		if (literal !== '') {
			html += `<span class="tok-literal">${literal}</span>`;
			index += literal.length;
			continue;
		}

		html += escapeHtml(char ?? '');
		index += 1;
	}

	return html;
}

export interface JsonTreeOptions {
	openDepth?: number;
}

function isContainer(value: unknown): value is Record<string, unknown> | unknown[] {
	return value !== null && typeof value === 'object';
}

function containerLabel(value: unknown): string {
	return Array.isArray(value)
		? `${value.length} item`
		: `${Object.keys(value as Record<string, unknown>).length} properti`;
}

function renderPrimitive(value: unknown): string {
	if (typeof value === 'string') {
		return `<span class="tok-string">"${escapeHtml(value)}"</span>`;
	}
	if (typeof value === 'number') {
		return `<span class="tok-number">${String(value)}</span>`;
	}
	if (typeof value === 'boolean') {
		return `<span class="tok-literal">${String(value)}</span>`;
	}
	return '<span class="tok-literal">null</span>';
}

function renderNode(
	value: unknown,
	key: string | null,
	depth: number,
	openDepth: number,
): string {
	const keyPart =
		key === null
			? ''
			: `<span class="tok-key">"${escapeHtml(key)}"</span><span class="tok-punct">: </span>`;

	if (!isContainer(value)) {
		return `<li>${keyPart}${renderPrimitive(value)}</li>`;
	}

	const entries: [string, unknown][] = Array.isArray(value)
		? value.map((item, itemIndex) => [String(itemIndex), item])
		: Object.entries(value);

	if (entries.length === 0) {
		const empty = Array.isArray(value) ? '[]' : '{}';
		return `<li>${keyPart}<span class="tok-punct">${empty}</span></li>`;
	}

	const children = entries
		.map(([childKey, child]) => renderNode(child, childKey, depth + 1, openDepth))
		.join('');
	const open = depth < openDepth ? ' open' : '';

	return `<li><details${open}><summary>${keyPart}<span class="json-tree__count">${containerLabel(value)}</span></summary><ul>${children}</ul></details></li>`;
}

export function renderJsonTree(data: unknown, options: JsonTreeOptions = {}): string {
	const openDepth = options.openDepth ?? 1;
	return `<ul class="json-tree">${renderNode(data, null, 0, openDepth)}</ul>`;
}

export type ToolbarAction =
	| 'bold'
	| 'italic'
	| 'heading'
	| 'list'
	| 'code'
	| 'link'
	| 'table';

export interface EditState {
	value: string;
	start: number;
	end: number;
}

function wrap(state: EditState, before: string, after: string, placeholder: string): EditState {
	const selected = state.value.slice(state.start, state.end);
	const inner = selected === '' ? placeholder : selected;
	const value =
		state.value.slice(0, state.start) + before + inner + after + state.value.slice(state.end);
	return {
		value,
		start: state.start + before.length,
		end: state.start + before.length + inner.length,
	};
}

function prefixLines(state: EditState, prefix: string): EditState {
	const value = state.value;
	const lineStart = value.lastIndexOf('\n', state.start - 1) + 1;
	let lineEnd = value.indexOf('\n', state.end);
	if (lineEnd === -1) lineEnd = value.length;

	const block = value.slice(lineStart, lineEnd);
	const lines = block.split('\n');
	const prefixed = lines
		.map((line) => (line.trim() === '' ? line : prefix + line))
		.join('\n');

	const nextValue = value.slice(0, lineStart) + prefixed + value.slice(lineEnd);
	const firstLineSkipped = lines[0] !== undefined && lines[0].trim() === '';
	const startDelta = firstLineSkipped ? 0 : prefix.length;

	return {
		value: nextValue,
		start: state.start + startDelta,
		end: state.end + (prefixed.length - block.length),
	};
}

function insertLink(state: EditState): EditState {
	const selected = state.value.slice(state.start, state.end);
	const label = selected === '' ? 'teks tautan' : selected;
	const url = 'url';
	const text = `[${label}](${url})`;
	const value = state.value.slice(0, state.start) + text + state.value.slice(state.end);
	const urlStart = state.start + label.length + 3;
	return { value, start: urlStart, end: urlStart + url.length };
}

function insertCode(state: EditState): EditState {
	const selected = state.value.slice(state.start, state.end);
	if (selected !== '' && !selected.includes('\n')) {
		return wrap(state, '`', '`', 'kode');
	}
	const inner = selected === '' ? 'kode' : selected;
	const block = '```\n' + inner + '\n```';
	const value = state.value.slice(0, state.start) + block + state.value.slice(state.end);
	const start = state.start + 4;
	return { value, start, end: start + inner.length };
}

const tableBlock =
	'| Kolom 1 | Kolom 2 | Kolom 3 |\n| --- | --- | --- |\n|  |  |  |';

function insertTable(state: EditState): EditState {
	const before = state.value.slice(0, state.start);
	const after = state.value.slice(state.end);
	let lead = '';
	if (before !== '' && !before.endsWith('\n')) lead = '\n\n';
	else if (before !== '' && !before.endsWith('\n\n')) lead = '\n';
	const tail = after !== '' && !after.startsWith('\n') ? '\n\n' : '';
	const value = before + lead + tableBlock + tail + after;
	const cursor = before.length + lead.length + 2;
	return { value, start: cursor, end: cursor + 'Kolom 1'.length };
}

export function applyToolbar(state: EditState, action: ToolbarAction): EditState {
	switch (action) {
		case 'bold':
			return wrap(state, '**', '**', 'teks tebal');
		case 'italic':
			return wrap(state, '*', '*', 'teks miring');
		case 'heading':
			return prefixLines(state, '## ');
		case 'list':
			return prefixLines(state, '- ');
		case 'code':
			return insertCode(state);
		case 'link':
			return insertLink(state);
		case 'table':
			return insertTable(state);
	}
}

export type ReadmeLicense = 'MIT' | 'Apache-2.0' | 'GPL-3.0';

export interface ReadmeInput {
	name: string;
	description: string;
	features: string;
	install: string;
	usage: string;
	license: ReadmeLicense | '';
	showLicenseBadge: boolean;
}

const badges: Record<ReadmeLicense, { image: string; link: string }> = {
	MIT: {
		image: 'https://img.shields.io/badge/License-MIT-yellow.svg',
		link: 'https://opensource.org/licenses/MIT',
	},
	'Apache-2.0': {
		image: 'https://img.shields.io/badge/License-Apache%202.0-blue.svg',
		link: 'https://www.apache.org/licenses/LICENSE-2.0',
	},
	'GPL-3.0': {
		image: 'https://img.shields.io/badge/License-GPLv3-blue.svg',
		link: 'https://www.gnu.org/licenses/gpl-3.0.html',
	},
};

function toLines(text: string): string[] {
	return text
		.split('\n')
		.map((line) => line.trim())
		.filter((line) => line !== '');
}

function toBullets(text: string): string[] {
	return toLines(text).map((line) => `- ${line.replace(/^[-*+]\s+/, '')}`);
}

export function generateReadme(input: ReadmeInput): string {
	const name = input.name.trim();
	if (name === '') return '';

	const parts: string[] = [`# ${name}`];

	const description = input.description.trim();
	if (description !== '') parts.push(description);

	if (input.showLicenseBadge && input.license !== '') {
		const badge = badges[input.license];
		parts.push(`[![Lisensi: ${input.license}](${badge.image})](${badge.link})`);
	}

	const features = toBullets(input.features);
	if (features.length > 0) {
		parts.push(['## Fitur', '', ...features].join('\n'));
	}

	const install = toLines(input.install);
	if (install.length > 0) {
		parts.push(['## Instalasi', '', '```bash', ...install, '```'].join('\n'));
	}

	const usage = input.usage.trim();
	if (usage !== '') parts.push(['## Cara pakai', '', usage].join('\n'));

	if (input.license !== '') parts.push(['## Lisensi', '', input.license].join('\n'));

	return parts.join('\n\n') + '\n';
}

export function slugify(value: string): string {
	return value
		.normalize('NFD')
		.replace(/[\u0300-\u036f]/g, '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-+/, '')
		.slice(0, 60)
		.replace(/-+$/, '');
}

export function markdownFilename(markdown: string): string {
	const heading = markdown.split('\n').find((line) => /^#\s+\S/.test(line));
	const name = heading ? slugify(heading.replace(/^#\s+/, '')) : '';
	return name === '' ? 'catatan.md' : `${name}.md`;
}

export async function copyText(text: string): Promise<boolean> {
	try {
		await navigator.clipboard.writeText(text);
		return true;
	} catch {
		/* clipboard API bisa diblokir, coba cara lama */
	}

	const area = document.createElement('textarea');
	area.value = text;
	area.setAttribute('readonly', '');
	area.style.position = 'fixed';
	area.style.top = '-1000px';
	document.body.append(area);
	area.select();

	let copied = false;
	try {
		copied = document.execCommand('copy');
	} catch {
		copied = false;
	}
	area.remove();
	return copied;
}

export function downloadText(
	filename: string,
	text: string,
	mime = 'text/markdown;charset=utf-8',
): void {
	const blob = new Blob([text], { type: mime });
	const url = URL.createObjectURL(blob);
	const link = document.createElement('a');
	link.href = url;
	link.download = filename;
	document.body.append(link);
	link.click();
	link.remove();
	URL.revokeObjectURL(url);
}

import { describe, expect, it } from 'vitest';
import {
	formatJson,
	highlightJson,
	lineColumnAt,
	minifyJson,
	parseJson,
	renderJsonTree,
} from './json-tools';

describe('parseJson', () => {
	it('membaca objek bersarang', () => {
		const result = parseJson('{"a":[1,true,null,"x"],"b":{"c":2.5}}');
		expect(result).toEqual({
			ok: true,
			data: { a: [1, true, null, 'x'], b: { c: 2.5 } },
		});
	});

	it('membaca escape dan unicode', () => {
		const result = parseJson('"baris\\n\\u00e9"');
		expect(result).toEqual({ ok: true, data: 'baris\né' });
	});

	it('menolak dokumen kosong', () => {
		const result = parseJson('   \n ');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Dokumen masih kosong.');
			expect(result.error.line).toBe(2);
		}
	});

	it('menunjuk baris dan kolom koma berlebih', () => {
		const result = parseJson('{\n  "a": 1,\n}');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Koma berlebih sebelum }.');
			expect(result.error.line).toBe(3);
			expect(result.error.column).toBe(1);
		}
	});

	it('menunjuk koma berlebih di array', () => {
		const result = parseJson('[1,]');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Koma berlebih sebelum ].');
			expect(result.error.column).toBe(4);
		}
	});

	it('menolak string tanpa penutup', () => {
		const result = parseJson('{"kunci": "nilai}');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Tanda kutip penutup belum ada.');
		}
	});

	it('menolak angka dengan nol di depan', () => {
		const result = parseJson('{"a": 01}');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Koma atau } dibutuhkan, bukan "1".');
		}
	});

	it('menolak teks setelah nilai', () => {
		const result = parseJson('{} {}');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Karakter "{" tidak terduga setelah nilai.');
			expect(result.error.column).toBe(4);
		}
	});

	it('menolak properti tanpa tanda kutip', () => {
		const result = parseJson('{a: 1}');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.message).toBe('Nama properti harus diapit tanda kutip.');
			expect(result.error.column).toBe(2);
		}
	});
});

describe('lineColumnAt', () => {
	it('menghitung kolom satu-based', () => {
		expect(lineColumnAt('abc\ndef', 0)).toEqual({ line: 1, column: 1 });
		expect(lineColumnAt('abc\ndef', 5)).toEqual({ line: 2, column: 2 });
		expect(lineColumnAt('abc\ndef', 99)).toEqual({ line: 2, column: 4 });
	});
});

describe('formatJson dan minifyJson', () => {
	it('merapikan dengan indentasi dua spasi', () => {
		const result = formatJson('{"a":1,"b":[2,3]}');
		expect(result.ok).toBe(true);
		if (result.ok) {
			expect(result.text).toBe('{\n  "a": 1,\n  "b": [\n    2,\n    3\n  ]\n}');
		}
	});

	it('memadatkan tanpa spasi', () => {
		const result = minifyJson('{\n  "a": 1,\n  "b": [2, 3]\n}');
		expect(result.ok).toBe(true);
		if (result.ok) {
			expect(result.text).toBe('{"a":1,"b":[2,3]}');
		}
	});

	it('meneruskan error tanpa mengubah teks', () => {
		const result = formatJson('{"a":}');
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error.line).toBe(1);
			expect(result.error.column).toBe(6);
		}
	});
});

describe('highlightJson', () => {
	it('membedakan kunci, string, angka, dan literal', () => {
		const html = highlightJson('{"a": 1, "b": "x<y", "c": true, "d": null}');
		expect(html).toContain('<span class="tok-key">"a"</span>');
		expect(html).toContain('<span class="tok-string">"x&lt;y"</span>');
		expect(html).toContain('<span class="tok-number">1</span>');
		expect(html).toContain('<span class="tok-literal">true</span>');
		expect(html).toContain('<span class="tok-literal">null</span>');
	});

	it('meng-escape tag di dalam string', () => {
		const html = highlightJson('{"x": "<script>alert(1)</script>"}');
		expect(html).not.toContain('<script>');
		expect(html).toContain('&lt;script&gt;');
	});
});

describe('renderJsonTree', () => {
	const data = { a: [1, 'x<'], b: {}, c: null, 'k"unci': true };

	it('membuat details yang bisa dilipat', () => {
		const html = renderJsonTree(data);
		expect(html.startsWith('<ul class="json-tree">')).toBe(true);
		expect(html).toContain('<details open>');
		expect((html.match(/<details open>/g) ?? []).length).toBe(1);
	});

	it('menampilkan jumlah item dan properti', () => {
		const html = renderJsonTree(data);
		expect(html).toContain('2 item');
		expect(html).toContain('4 properti');
	});

	it('meng-escape kunci dan string', () => {
		const html = renderJsonTree(data);
		expect(html).toContain('"k&quot;unci"');
		expect(html).toContain('"x&lt;"');
	});

	it('menulis objek kosong tanpa details', () => {
		const html = renderJsonTree({ kosong: {}, daftar: [] });
		expect(html).toContain('<span class="tok-punct">{}</span>');
		expect(html).toContain('<span class="tok-punct">[]</span>');
	});

	it('membuka node sesuai openDepth', () => {
		const html = renderJsonTree({ a: { b: { c: 1 } } }, { openDepth: 2 });
		expect((html.match(/<details open>/g) ?? []).length).toBe(2);
	});
});

import { describe, expect, it } from 'vitest';
import { applyToolbar, type EditState } from './markdown-toolbar';

function state(value: string, start: number, end = start): EditState {
	return { value, start, end };
}

function selected(next: EditState): string {
	return next.value.slice(next.start, next.end);
}

describe('applyToolbar', () => {
	it('membungkus teks terpilih dengan tebal', () => {
		const next = applyToolbar(state('halo dunia', 5, 10), 'bold');
		expect(next.value).toBe('halo **dunia**');
		expect(selected(next)).toBe('dunia');
	});

	it('mengisi placeholder saat tidak ada pilihan', () => {
		const next = applyToolbar(state('', 0), 'bold');
		expect(next.value).toBe('**teks tebal**');
		expect(selected(next)).toBe('teks tebal');
	});

	it('membungkus teks terpilih dengan miring', () => {
		const next = applyToolbar(state('kata', 0, 4), 'italic');
		expect(next.value).toBe('*kata*');
		expect(selected(next)).toBe('kata');
	});

	it('memberi awalan judul ke setiap baris', () => {
		const next = applyToolbar(state('satu\ndua', 0, 8), 'heading');
		expect(next.value).toBe('## satu\n## dua');
		expect(next.start).toBe(3);
	});

	it('melewati baris kosong saat memberi awalan daftar', () => {
		const next = applyToolbar(state('\nsatu', 0, 5), 'list');
		expect(next.value).toBe('\n- satu');
		expect(next.start).toBe(0);
	});

	it('memakai kutip satu untuk kode sebaris', () => {
		const next = applyToolbar(state('npm install', 0, 11), 'code');
		expect(next.value).toBe('`npm install`');
		expect(selected(next)).toBe('npm install');
	});

	it('memakai blok kode untuk pilihan multi baris', () => {
		const next = applyToolbar(state('baris 1\nbaris 2', 0, 15), 'code');
		expect(next.value).toBe('```\nbaris 1\nbaris 2\n```');
		expect(selected(next)).toBe('baris 1\nbaris 2');
	});

	it('menaruh kursor di alamat tautan', () => {
		const next = applyToolbar(state('lihat dokumen', 6, 13), 'link');
		expect(next.value).toBe('lihat [dokumen](url)');
		expect(selected(next)).toBe('url');
	});

	it('memberi label bawaan saat tautan tanpa pilihan', () => {
		const next = applyToolbar(state('', 0), 'link');
		expect(next.value).toBe('[teks tautan](url)');
		expect(selected(next)).toBe('url');
	});

	it('menyisipkan tabel dan memilih sel pertama', () => {
		const next = applyToolbar(state('', 0), 'table');
		expect(next.value.startsWith('| Kolom 1 | Kolom 2 | Kolom 3 |')).toBe(true);
		expect(next.value).toContain('| --- | --- | --- |');
		expect(selected(next)).toBe('Kolom 1');
	});

	it('memberi jarak sebelum tabel saat sudah ada teks', () => {
		const next = applyToolbar(state('catatan', 7), 'table');
		expect(next.value.startsWith('catatan\n\n| Kolom 1 |')).toBe(true);
	});
});

