/* Layout alat hidup (Generator) */
.tool-body--live {
	grid-template-columns: minmax(0, 1fr);
}

.live-tool {
	min-width: 0;
}

.tool-shell {
	border: 1px solid var(--border);
	border-radius: var(--radius-lg);
	background: var(--surface);
	overflow: hidden;
}

.tool-panel {
	padding: var(--space-4);
}

.tool-panel[hidden] {
	display: none;
}

.pane-grid {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--space-4);
}

@media (min-width: 900px) {
	.pane-grid--split {
		grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
	}
}

.pane {
	display: flex;
	flex-direction: column;
	gap: var(--space-3);
	min-width: 0;
}

.pane__head {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	justify-content: space-between;
	gap: var(--space-2);
}

.pane__title {
	font-size: 1rem;
	font-weight: 600;
}

.pane-actions {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: var(--space-2);
}

.pane-actions .btn {
	min-height: 44px;
	padding: 0 var(--space-3);
	font-size: 0.875rem;
}

.toolbar {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-1);
}

.toolbar__btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 44px;
	height: 44px;
	border: 1px solid var(--border);
	border-radius: var(--radius-sm);
	background: var(--surface-2);
	color: var(--text-muted);
}

.toolbar__btn:hover {
	color: var(--text);
	border-color: var(--border-strong);
}

.code-area,
.code-block {
	width: 100%;
	min-height: 320px;
	margin: 0;
	padding: var(--space-3);
	border: 1px solid var(--border);
	border-radius: var(--radius-md);
	background: var(--surface-2);
	color: var(--text);
	font-family: var(--font-mono);
	font-size: 0.875rem;
	line-height: 1.57;
	resize: vertical;
	overflow: auto;
	white-space: pre;
	tab-size: 2;
}

.code-area:focus-visible {
	outline: none;
	border-color: var(--accent);
	box-shadow: var(--ring);
}

.code-area[aria-invalid="true"] {
	border-color: var(--danger);
}

.preview {
	min-height: 320px;
	padding: var(--space-4);
	border: 1px solid var(--border);
	border-radius: var(--radius-md);
	background: var(--surface-2);
	overflow-wrap: anywhere;
}

.preview[hidden],
.preview-empty[hidden],
.alert[hidden],
.codeblock__lang[hidden] {
	display: none;
}

.preview-empty {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	min-height: 320px;
	padding: var(--space-4);
	border: 1px dashed var(--border-strong);
	border-radius: var(--radius-md);
	color: var(--text-muted);
	font-size: 0.875rem;
}

.prose h1,
.prose h2,
.prose h3 {
	margin: var(--space-4) 0 var(--space-2);
	font-size: 1.125rem;
	font-weight: 700;
}

.prose h1:first-child,
.prose h2:first-child,
.prose h3:first-child {
	margin-top: 0;
}

.prose p,
.prose ul,
.prose ol,
.prose table,
.prose .codeblock,
.prose blockquote {
	margin: 0 0 var(--space-3);
}

.prose ul,
.prose ol {
	padding-left: var(--space-5);
}

.prose ul.contains-task-list {
	list-style: none;
	padding-left: 0;
}

.prose li > input[type="checkbox"] {
	margin-right: var(--space-2);
	accent-color: var(--accent);
}

.prose a {
	color: var(--accent-hover);
	text-decoration: underline;
	text-underline-offset: 2px;
}

.prose code {
	padding: 1px 4px;
	border-radius: 4px;
	background: var(--surface);
	font-family: var(--font-mono);
	font-size: 0.875em;
}

.prose table {
	display: block;
	max-width: 100%;
	overflow-x: auto;
	border-collapse: collapse;
}

.prose th,
.prose td {
	padding: var(--space-1) var(--space-2);
	border: 1px solid var(--border);
	text-align: left;
	vertical-align: top;
}

.prose th {
	background: var(--surface);
	font-weight: 600;
}

.prose img {
	max-width: 100%;
	height: auto;
}

.prose blockquote {
	padding-left: var(--space-3);
	border-left: 3px solid var(--border-strong);
	color: var(--text-muted);
}

.codeblock {
	position: relative;
	margin: 0 0 var(--space-3);
}

.codeblock pre {
	margin: 0;
	padding: var(--space-3);
	border: 1px solid var(--border);
	border-radius: var(--radius-md);
	background: var(--surface-2);
	overflow-x: auto;
	font-size: 0.875rem;
	line-height: 1.57;
}

.codeblock code {
	font-family: var(--font-mono);
	background: none;
	padding: 0;
}

.codeblock__lang {
	position: absolute;
	top: var(--space-1);
	right: var(--space-2);
	font-family: var(--font-mono);
	font-size: 0.6875rem;
	letter-spacing: 0.06em;
	text-transform: uppercase;
	color: var(--text-muted);
}

.form-grid {
	display: grid;
	gap: var(--space-4);
}

.check-row {
	display: flex;
	align-items: center;
	gap: var(--space-2);
	min-height: 44px;
	font-size: 0.9375rem;
}

.check-row input {
	width: 20px;
	height: 20px;
	accent-color: var(--accent);
}

.check-hint {
	margin-top: 0;
}

.segmented {
	display: inline-flex;
	padding: 2px;
	border: 1px solid var(--border-strong);
	border-radius: var(--radius-md);
	background: var(--surface-2);
}

.segmented__btn {
	min-height: 40px;
	padding: 0 var(--space-3);
	border: 0;
	border-radius: var(--radius-sm);
	background: transparent;
	color: var(--text-muted);
	font-family: var(--font-display);
	font-size: 0.875rem;
	font-weight: 600;
}

.segmented__btn[aria-pressed="true"] {
	background: var(--surface);
	color: var(--text);
	box-shadow: var(--shadow-sm);
}

.alert {
	display: flex;
	align-items: flex-start;
	gap: var(--space-2);
	padding: var(--space-3);
	border-radius: var(--radius-md);
	background: color-mix(in srgb, var(--danger) 10%, transparent);
	color: var(--danger);
	font-size: 0.875rem;
}

.alert p {
	color: var(--text);
}

.json-tree-wrap {
	min-height: 320px;
	padding: var(--space-3);
	border: 1px solid var(--border);
	border-radius: var(--radius-md);
	background: var(--surface-2);
	overflow: auto;
	font-family: var(--font-mono);
	font-size: 0.875rem;
	line-height: 1.6;
}

.json-tree,
.json-tree ul {
	margin: 0;
	padding: 0 0 0 var(--space-4);
	list-style: none;
}

.json-tree > li {
	padding-left: 0;
}

.json-tree summary {
	cursor: pointer;
	min-height: 28px;
}

.json-tree__count {
	margin-left: var(--space-2);
	color: var(--text-muted);
	font-size: 0.75rem;
}

.tok-key {
	color: var(--info);
}

.tok-string {
	color: var(--success);
}

.tok-number,
.tok-literal {
	color: var(--warning);
}

.tok-punct {
	color: var(--text-muted);
}

.mt-3 {
	margin-top: var(--space-3);
}

/* Halaman teks */
.prose-page {

