export type PageRangeResult =
	| { ok: true; pages: number[] }
	| { ok: false; message: string };

export function parsePageRange(input: string, pageCount: number): PageRangeResult {
	const text = input.replace(/\s+/g, '');
	if (text === '') return { ok: false, message: 'Tulis halaman yang mau diambil, misalnya 1-3,5.' };

	const pages = new Set<number>();
	for (const part of text.split(',')) {
		if (part === '') return { ok: false, message: 'Ada koma berlebih di rentang halaman.' };

		const match = /^(\d+)(?:-(\d+))?$/.exec(part);
		if (!match) return { ok: false, message: `"${part}" bukan rentang halaman yang sah.` };

		const from = Number(match[1]);
		const to = match[2] === undefined ? from : Number(match[2]);
		if (from < 1 || to < 1) return { ok: false, message: 'Nomor halaman mulai dari 1.' };
		if (to < from) return { ok: false, message: `Rentang ${part} terbalik. Tulis yang kecil dulu.` };
		if (to > pageCount) {
			return { ok: false, message: `PDF ini hanya punya ${pageCount} halaman.` };
		}
		for (let page = from; page <= to; page += 1) pages.add(page);
	}

	return { ok: true, pages: [...pages].sort((a, b) => a - b) };
}

export function formatBytes(bytes: number): string {
	if (bytes < 1024) return `${bytes} B`;
	if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
	return `${(bytes / (1024 * 1024)).toFixed(1).replace('.', ',')} MB`;
}

export function reductionPercent(before: number, after: number): number {
	if (before <= 0) return 0;
	return Math.round(((before - after) / before) * 100);
}

import { describe, expect, it } from 'vitest';
import { formatBytes, parsePageRange, reductionPercent } from './page-range';

describe('parsePageRange', () => {
	it('membaca rentang dan halaman tunggal', () => {
		expect(parsePageRange('1-3,5', 10)).toEqual({ ok: true, pages: [1, 2, 3, 5] });
	});

	it('membuang duplikat dan mengurutkan', () => {
		expect(parsePageRange('5, 2-3, 3', 10)).toEqual({ ok: true, pages: [2, 3, 5] });
	});

	it('menolak kosong', () => {
		expect(parsePageRange('  ', 10).ok).toBe(false);
	});

	it('menolak rentang terbalik', () => {
		const result = parsePageRange('5-2', 10);
		expect(result.ok).toBe(false);
		if (!result.ok) expect(result.message).toContain('terbalik');
	});

	it('menolak halaman di atas jumlah halaman', () => {
		const result = parsePageRange('1-12', 10);
		expect(result).toEqual({ ok: false, message: 'PDF ini hanya punya 10 halaman.' });
	});

	it('menolak nol dan teks', () => {
		expect(parsePageRange('0', 3).ok).toBe(false);
		expect(parsePageRange('satu', 3).ok).toBe(false);
	});
});

describe('formatBytes', () => {
	it('memakai satuan yang sesuai', () => {
		expect(formatBytes(512)).toBe('512 B');
		expect(formatBytes(2048)).toBe('2 KB');
		expect(formatBytes(2.4 * 1024 * 1024)).toBe('2,4 MB');
	});
});

describe('reductionPercent', () => {
	it('menghitung persen pengurangan', () => {
		expect(reductionPercent(2_400_000, 900_000)).toBe(63);
	});

	it('bisa negatif saat hasil lebih besar', () => {
		expect(reductionPercent(100, 120)).toBe(-20);
	});
});

import { PDFDocument, degrees } from 'pdf-lib';

export type Orientation = 'portrait' | 'landscape' | 'auto';
export type Margin = 'none' | 'small' | 'large';
export type CompressLevel = 'ringan' | 'sedang' | 'maksimal';

const marginPoints: Record<Margin, number> = { none: 0, small: 24, large: 48 };

const compressProfile: Record<CompressLevel, { scale: number; quality: number }> = {
	ringan: { scale: 1.5, quality: 0.85 },
	sedang: { scale: 1.2, quality: 0.7 },
	maksimal: { scale: 1, quality: 0.5 },
};

export async function mergePdfs(files: ArrayBuffer[]): Promise<Uint8Array> {
	const out = await PDFDocument.create();
	for (const bytes of files) {
		const source = await PDFDocument.load(bytes, { ignoreEncryption: false });
		const pages = await out.copyPages(source, source.getPageIndices());
		pages.forEach((page) => out.addPage(page));
	}
	return out.save();
}

export async function splitPdf(bytes: ArrayBuffer, pages: number[]): Promise<Uint8Array> {
	const source = await PDFDocument.load(bytes);
	const out = await PDFDocument.create();
	const copied = await out.copyPages(
		source,
		pages.map((page) => page - 1),
	);
	copied.forEach((page) => out.addPage(page));
	return out.save();
}

export async function imagesToPdf(
	images: { bytes: ArrayBuffer; type: 'jpg' | 'png' }[],
	options: { orientation: Orientation; margin: Margin },
): Promise<Uint8Array> {
	const out = await PDFDocument.create();
	const pad = marginPoints[options.margin];

	for (const image of images) {
		const embedded =
			image.type === 'png' ? await out.embedPng(image.bytes) : await out.embedJpg(image.bytes);
		const naturalLandscape = embedded.width > embedded.height;
		const landscape =
			options.orientation === 'auto' ? naturalLandscape : options.orientation === 'landscape';

		const pageWidth = landscape ? 842 : 595;
		const pageHeight = landscape ? 595 : 842;
		const page = out.addPage([pageWidth, pageHeight]);

		const maxW = pageWidth - pad * 2;
		const maxH = pageHeight - pad * 2;
		const scale = Math.min(maxW / embedded.width, maxH / embedded.height);
		const w = embedded.width * scale;
		const h = embedded.height * scale;

		page.drawImage(embedded, {
			x: (pageWidth - w) / 2,
			y: (pageHeight - h) / 2,
			width: w,
			height: h,
		});
	}

	return out.save();
}

export async function rotatePageDegrees(bytes: ArrayBuffer): Promise<Uint8Array> {
	const doc = await PDFDocument.load(bytes);
	doc.getPages().forEach((page) => page.setRotation(degrees((page.getRotation().angle + 90) % 360)));
	return doc.save();
}

export interface RenderedPage {
	width: number;
	height: number;
	jpeg: Uint8Array;
}

export async function rebuildCompressed(
	pages: RenderedPage[],
): Promise<Uint8Array> {
	const out = await PDFDocument.create();
	for (const page of pages) {
		const image = await out.embedJpg(page.jpeg);
		const pdfPage = out.addPage([page.width, page.height]);
		pdfPage.drawImage(image, { x: 0, y: 0, width: page.width, height: page.height });
	}
	return out.save();
}

export function compressSettings(level: CompressLevel) {
	return compressProfile[level];
}

import * as pdfjs from 'pdfjs-dist';
import pdfWorkerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
import {
	compressSettings,
	imagesToPdf,
	mergePdfs,
	rebuildCompressed,
	splitPdf,
	type CompressLevel,
	type Margin,
	type Orientation,
	type RenderedPage,
} from './pdf-ops';

pdfjs.GlobalWorkerOptions.workerSrc = pdfWorkerUrl;

export type WorkerRequest =
	| { id: number; op: 'merge'; files: ArrayBuffer[] }
	| { id: number; op: 'split'; file: ArrayBuffer; pages: number[] }
	| {
			id: number;
			op: 'images';
			images: { bytes: ArrayBuffer; type: 'jpg' | 'png' }[];
			orientation: Orientation;
			margin: Margin;
	  }
	| { id: number; op: 'compress'; file: ArrayBuffer; level: CompressLevel };

export type WorkerResponse =
	| { id: number; type: 'progress'; done: number; total: number }
	| { id: number; type: 'result'; bytes: Uint8Array; pageCount?: number }
	| { id: number; type: 'error'; message: string };

async function renderPages(bytes: ArrayBuffer, level: CompressLevel, id: number): Promise<RenderedPage[]> {
	const { scale, quality } = compressSettings(level);
	const doc = await pdfjs.getDocument({ data: new Uint8Array(bytes), isEvalSupported: false }).promise;
	const pages: RenderedPage[] = [];

	for (let index = 1; index <= doc.numPages; index += 1) {
		const page = await doc.getPage(index);
		const viewport = page.getViewport({ scale });
		const canvas = new OffscreenCanvas(Math.ceil(viewport.width), Math.ceil(viewport.height));
		const context = canvas.getContext('2d');
		if (!context) throw new Error('Kanvas tidak tersedia di worker.');

		await page.render({ canvasContext: context as unknown as CanvasRenderingContext2D, viewport, canvas: canvas as unknown as HTMLCanvasElement }).promise;
		const blob = await canvas.convertToBlob({ type: 'image/jpeg', quality });
		const jpeg = new Uint8Array(await blob.arrayBuffer());

		pages.push({ width: viewport.width, height: viewport.height, jpeg });
		postMessage({ id, type: 'progress', done: index, total: doc.numPages } satisfies WorkerResponse);
	}

	await doc.destroy();
	return pages;
}

self.onmessage = async (event: MessageEvent<WorkerRequest>) => {
	const request = event.data;
	try {
		let bytes: Uint8Array;
		let pageCount: number | undefined;

		if (request.op === 'merge') {
			bytes = await mergePdfs(request.files);
		} else if (request.op === 'split') {
			bytes = await splitPdf(request.file, request.pages);
			pageCount = request.pages.length;
		} else if (request.op === 'images') {
			bytes = await imagesToPdf(request.images, {
				orientation: request.orientation,
				margin: request.margin,
			});
		} else {
			const pages = await renderPages(request.file, request.level, request.id);
			bytes = await rebuildCompressed(pages);
			pageCount = pages.length;
		}

		const response: WorkerResponse = { id: request.id, type: 'result', bytes, pageCount };
		postMessage(response, [bytes.buffer as ArrayBuffer]);
	} catch (error) {
		const message = error instanceof Error ? error.message : 'Gagal memproses PDF.';
		postMessage({ id: request.id, type: 'error', message } satisfies WorkerResponse);
	}
};

