export interface DiagramTemplate {
	id: string;
	label: string;
	code: string;
}

export const diagramTemplates: DiagramTemplate[] = [
	{
		id: 'flowchart',
		label: 'Flowchart',
		code: `flowchart TD
  A[Mulai] --> B{Stok ada?}
  B -- Ya --> C[Proses pesanan]
  B -- Tidak --> D[Beri tahu pelanggan]
  C --> E[Selesai]
  D --> E`,
	},
	{
		id: 'sequence',
		label: 'Sequence',
		code: `sequenceDiagram
  participant U as Pengguna
  participant A as Aplikasi
  participant S as Server
  U->>A: Klik unduh
  A->>S: Minta berkas
  S-->>A: Kirim berkas
  A-->>U: Tampilkan hasil`,
	},
	{
		id: 'erd',
		label: 'ERD',
		code: `erDiagram
  MAHASISWA ||--o{ KRS : mengambil
  MATKUL ||--o{ KRS : masuk
  MAHASISWA {
    string nim PK
    string nama
  }
  MATKUL {
    string kode PK
    string judul
  }`,
	},
	{
		id: 'class',
		label: 'Class',
		code: `classDiagram
  class Hewan {
    +String nama
    +bersuara()
  }
  class Kucing {
    +mengeong()
  }
  Hewan <|-- Kucing`,
	},
	{
		id: 'gantt',
		label: 'Gantt',
		code: `gantt
  title Rencana skripsi
  dateFormat YYYY-MM-DD
  section Riset
  Studi pustaka :a1, 2026-01-05, 14d
  Pengumpulan data :a2, after a1, 21d
  section Penulisan
  Draf bab 1-3 :b1, after a2, 28d`,
	},
	{
		id: 'state',
		label: 'State',
		code: `stateDiagram-v2
  [*] --> Draf
  Draf --> Terkirim: kirim
  Terkirim --> Disetujui: setuju
  Terkirim --> Draf: revisi
  Disetujui --> [*]`,
	},
];

export function getTemplate(id: string): DiagramTemplate | undefined {
	return diagramTemplates.find((item) => item.id === id);
}

export interface SyntaxIssue {
	line: number;
	message: string;
}

const lineMatch = /(?:line|baris)\s+(\d+)/i;

export function extractLineFromMermaidError(error: unknown, source: string): SyntaxIssue {
	const raw = error instanceof Error ? error.message : String(error ?? '');
	const hash = (error as { hash?: { line?: number | string } } | null)?.hash;
	const fromHash = hash?.line !== undefined ? Number(hash.line) + 1 : NaN;
	const fromText = Number(lineMatch.exec(raw)?.[1]);

	const totalLines = Math.max(1, source.split('\n').length);
	let line = Number.isFinite(fromHash) ? fromHash : fromText;
	if (!Number.isFinite(line)) line = 1;
	line = Math.min(Math.max(1, Math.trunc(line)), totalLines);

	const message = raw
		.split('\n')
		.map((part) => part.trim())
		.find((part) => part !== '' && !part.startsWith('Parse error') && !part.startsWith('-'));

	return {
		line,
		message: message ?? 'Sintaks Mermaid tidak dikenali.',
	};
}

import { describe, expect, it } from 'vitest';
import { diagramTemplates, getTemplate } from './templates';
import { extractLineFromMermaidError } from './error-line';

describe('templates', () => {
	it('menyediakan enam jenis diagram sesuai PRD', () => {
		expect(diagramTemplates.map((item) => item.id)).toEqual([
			'flowchart',
			'sequence',
			'erd',
			'class',
			'gantt',
			'state',
		]);
	});

	it('setiap template dimulai dengan kata kunci diagram', () => {
		const keywords = ['flowchart', 'sequenceDiagram', 'erDiagram', 'classDiagram', 'gantt', 'stateDiagram-v2'];
		diagramTemplates.forEach((item, index) => {
			expect(item.code.startsWith(keywords[index]!)).toBe(true);
		});
	});

	it('mencari template berdasarkan id', () => {
		expect(getTemplate('erd')?.label).toBe('ERD');
		expect(getTemplate('tidak-ada')).toBeUndefined();
	});
});

describe('extractLineFromMermaidError', () => {
	const source = 'flowchart TD\n  A --> B\n  B --> ?';

	it('memakai hash.line dari Mermaid (berbasis nol)', () => {
		const error = Object.assign(new Error('Ada yang salah'), { hash: { line: 2 } });
		expect(extractLineFromMermaidError(error, source).line).toBe(3);
	});

	it('membaca nomor baris dari teks pesan', () => {
		const result = extractLineFromMermaidError(new Error('Parse error on line 2:\n  A --> B'), source);
		expect(result.line).toBe(2);
	});

	it('membatasi nomor baris ke jumlah baris sumber', () => {
		const error = Object.assign(new Error('x'), { hash: { line: 99 } });
		expect(extractLineFromMermaidError(error, source).line).toBe(3);
	});

	it('jatuh ke baris 1 kalau tidak ada informasi', () => {
		expect(extractLineFromMermaidError(new Error('gagal'), source).line).toBe(1);
	});

	it('mengambil pesan pertama yang bermakna', () => {
		const result = extractLineFromMermaidError(
			new Error('Parse error on line 3:\n---\nExpecting ARROW, got ?'),
			source,
		);
		expect(result.message).toBe('Expecting ARROW, got ?');
	});
});

