let loading: Promise<(file: Blob) => Promise<Blob>> | null = null;

export function loadPhotoModule(onProgress: ProgressFn): Promise<(file: Blob) => Promise<Blob>> {
	loading ??= import('@imgly/background-removal').then((module) => {
