import { AwsClient } from 'aws4fetch';

export interface R2Env {
	R2_ACCOUNT_ID: string;
	R2_ACCESS_KEY_ID: string;
	R2_SECRET_ACCESS_KEY: string;
	R2_BUCKET: string;
}

const PRESIGN_SECONDS = 15 * 60;

function client(env: R2Env): AwsClient {
	return new AwsClient({
		accessKeyId: env.R2_ACCESS_KEY_ID,
		secretAccessKey: env.R2_SECRET_ACCESS_KEY,
		service: 's3',
		region: 'auto',
	});
}

function objectUrl(env: R2Env, key: string): string {
	return `https://${env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com/${env.R2_BUCKET}/${key}`;
}

export async function presignUpload(
	env: R2Env,
	key: string,
	contentType: string,
	contentLength: number,
): Promise<string> {
	const url = new URL(objectUrl(env, key));
	url.searchParams.set('X-Amz-Expires', String(PRESIGN_SECONDS));
	const signed = await client(env).sign(url.toString(), {
		method: 'PUT',
		aws: { signQuery: true },
		headers: {
			'Content-Type': contentType,
			'Content-Length': String(contentLength),
		},
	});
	return signed.url;
}

export async function presignDownload(env: R2Env, key: string): Promise<string> {
	const signed = await client(env).sign(objectUrl(env, key), {
		method: 'GET',
		aws: { signQuery: true },
	});
	return signed.url;
}

export async function deleteObject(env: R2Env, key: string): Promise<void> {
	const response = await client(env).fetch(objectUrl(env, key), { method: 'DELETE' });
	if (!response.ok && response.status !== 404) {
		throw new Error(`Gagal menghapus objek ${key}: ${response.status}`);
	}
}

export interface RateLimitBinding {
	limit: (options: { key: string }) => Promise<{ success: boolean }>;
}

export async function allowRequest(
	binding: RateLimitBinding | undefined,
	ip: string,
): Promise<boolean> {
	if (!binding) return true;
	const result = await binding.limit({ key: ip });
	return result.success;
}

export function clientIp(request: Request): string {
	return request.headers.get('CF-Connecting-IP') ?? 'unknown';
}

import type { APIRoute } from 'astro';
import { allowRequest, clientIp, type RateLimitBinding } from '../../../features/kirim-file/rate-limit';
import {
	MAX_FILE_BYTES,
	expiresAt,
	isExpiryId,
	randomToken,
	sanitizeFileName,
	validateFile,
} from '../../../features/kirim-file/share-rules';
import { presignUpload, type R2Env } from '../../../features/kirim-file/r2';
import type { SharesDb } from '../../../features/kirim-file/db';

export const prerender = false;

interface Env extends R2Env {
	DB: SharesDb;
	UPLOAD_LIMIT: RateLimitBinding;
}

interface Body {
	files: { name: string; size: number; type: string }[];
	expiry: string;
}

function json(data: unknown, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
	});
}

export const POST: APIRoute = async ({ request, locals }) => {
	const env = (locals as { runtime?: { env: Env } }).runtime?.env;
	if (!env) return json({ error: 'Layanan belum dikonfigurasi.' }, 503);

	if (!(await allowRequest(env.UPLOAD_LIMIT, clientIp(request)))) {
		return json({ error: 'Terlalu banyak unggahan dari jaringanmu. Coba lagi sebentar.' }, 429);
	}

	let body: Body;
	try {
		body = (await request.json()) as Body;
	} catch {
		return json({ error: 'Permintaan tidak valid.' }, 400);
	}

	if (!isExpiryId(body.expiry)) return json({ error: 'Masa berlaku tidak dikenal.' }, 400);
	if (!Array.isArray(body.files) || body.files.length === 0 || body.files.length > 10) {
		return json({ error: 'Pilih 1 sampai 10 berkas.' }, 400);
	}

	for (const file of body.files) {
		const problem = validateFile(file);
		if (problem) return json({ error: problem }, 400);
	}

	const shareId = randomToken(16);
	const now = Date.now();
	const expiry = expiresAt(now, body.expiry);

	const files = await Promise.all(
		body.files.map(async (file, index) => {
			const safe = sanitizeFileName(file.name);
			const key = `${shareId}/${index}-${safe}`;
			const uploadUrl = await presignUpload(env, key, file.type || 'application/octet-stream', file.size);
			return { key, name: safe, size: file.size, type: file.type, uploadUrl };
		}),
	);

	await env.DB.prepare(
		'INSERT INTO shares (id, expires_at, created_at, status) VALUES (?, ?, ?, ?)',
	)
		.bind(shareId, expiry, now, 'uploading')
		.run();

	for (const file of files) {
		await env.DB.prepare(
			'INSERT INTO share_files (share_id, object_key, name, size, mime) VALUES (?, ?, ?, ?, ?)',
		)
			.bind(shareId, file.key, file.name, file.size, file.type)
			.run();
	}

	return json({
		id: shareId,
		expiresAt: expiry,
		maxBytes: MAX_FILE_BYTES,
		uploads: files.map((file) => ({ name: file.name, uploadUrl: file.uploadUrl })),
	});
};

export interface SharesDb {
	prepare: (sql: string) => {
		bind: (...values: unknown[]) => {
			run: () => Promise<unknown>;
			first: <T = unknown>() => Promise<T | null>;
			all: <T = unknown>() => Promise<{ results: T[] }>;
		};
		all: <T = unknown>() => Promise<{ results: T[] }>;
	};
}

export interface ShareRow {
	id: string;
	expires_at: number;
	created_at: number;
	status: 'uploading' | 'ready' | 'deleted';
	max_downloads: number | null;
	downloads: number;
	reported: number;
}

export interface ShareFileRow {
	share_id: string;
	object_key: string;
	name: string;
	size: number;
	mime: string;
}

import type { APIRoute } from 'astro';
import type { SharesDb, ShareRow } from '../../../../features/kirim-file/db';
import { isExpired } from '../../../../features/kirim-file/share-rules';

export const prerender = false;

const ID_PATTERN = /^[0-9a-f]{32}$/;

export const POST: APIRoute = async ({ params, locals }) => {
	const env = (locals as { runtime?: { env: { DB: SharesDb } } }).runtime?.env;
	if (!env) return new Response('Layanan belum dikonfigurasi.', { status: 503 });

	const id = params.id ?? '';
	if (!ID_PATTERN.test(id)) return new Response('Tidak ditemukan.', { status: 404 });

	const row = await env.DB.prepare('SELECT * FROM shares WHERE id = ?').bind(id).first<ShareRow>();
	if (!row || row.status === 'deleted') return new Response('Tidak ditemukan.', { status: 404 });

	await env.DB.prepare('UPDATE shares SET status = ? WHERE id = ?').bind('ready', id).run();
	return Response.json({ ok: true, expired: isExpired(row.expires_at, Date.now()) });
};

import type { APIRoute } from 'astro';
import type { SharesDb, ShareFileRow, ShareRow } from '../../../../features/kirim-file/db';
import { presignDownload, type R2Env } from '../../../../features/kirim-file/r2';
import { isExpired } from '../../../../features/kirim-file/share-rules';

export const prerender = false;

const ID_PATTERN = /^[0-9a-f]{32}$/;

interface Env extends R2Env {
	DB: SharesDb;
}

export const GET: APIRoute = async ({ params, locals }) => {
	const env = (locals as { runtime?: { env: Env } }).runtime?.env;
	if (!env) return new Response('Layanan belum dikonfigurasi.', { status: 503 });

	const id = params.id ?? '';
	if (!ID_PATTERN.test(id)) return new Response('Tidak ditemukan.', { status: 404 });

	const row = await env.DB.prepare('SELECT * FROM shares WHERE id = ?').bind(id).first<ShareRow>();
	if (!row || row.status !== 'ready') {
		return Response.json({ error: 'Link tidak ditemukan atau sudah dihapus.' }, { status: 404 });
	}

	const now = Date.now();
	if (isExpired(row.expires_at, now)) {
		return Response.json({ error: 'Link sudah kedaluwarsa.', expired: true }, { status: 410 });
	}

	const { results } = await env.DB.prepare('SELECT * FROM share_files WHERE share_id = ?')
		.bind(id)
		.all<ShareFileRow>();

	const files = await Promise.all(
		results.map(async (file) => ({
			name: file.name,
			size: file.size,
			downloadUrl: await presignDownload(env, file.object_key),
		})),
	);

	return Response.json({
		id,
		expiresAt: row.expires_at,
		remainingMs: Math.max(0, row.expires_at - now),
		files,
	});
};

import type { APIRoute } from 'astro';
import type { SharesDb } from '../../../../features/kirim-file/db';
import { allowRequest, clientIp, type RateLimitBinding } from '../../../../features/kirim-file/rate-limit';

export const prerender = false;

const ID_PATTERN = /^[0-9a-f]{32}$/;

interface Env {
	DB: SharesDb;
	REPORT_LIMIT: RateLimitBinding;
}

export const POST: APIRoute = async ({ params, request, locals }) => {
	const env = (locals as { runtime?: { env: Env } }).runtime?.env;
	if (!env) return new Response('Layanan belum dikonfigurasi.', { status: 503 });

	if (!(await allowRequest(env.REPORT_LIMIT, clientIp(request)))) {
		return Response.json({ error: 'Terlalu sering melapor. Coba lagi nanti.' }, { status: 429 });
	}

	const id = params.id ?? '';
	if (!ID_PATTERN.test(id)) return new Response('Tidak ditemukan.', { status: 404 });

	let reason = '';
	try {
		const body = (await request.json()) as { reason?: unknown };
		reason = typeof body.reason === 'string' ? body.reason.slice(0, 500) : '';
	} catch {
		reason = '';
	}

	await env.DB.prepare('UPDATE shares SET reported = reported + 1 WHERE id = ?').bind(id).run();
	await env.DB.prepare('INSERT INTO reports (share_id, reason, created_at) VALUES (?, ?, ?)')
		.bind(id, reason, Date.now())
		.run();

	return Response.json({ ok: true });
};

import type { SharesDb, ShareFileRow } from './db';
import { deleteObject, type R2Env } from './r2';

export interface CleanupEnv extends R2Env {
	DB: SharesDb;
}

const BATCH = 50;

export async function removeExpiredShares(env: CleanupEnv, now = Date.now()): Promise<number> {
	const { results } = await env.DB.prepare(
		"SELECT id FROM shares WHERE status != 'deleted' AND expires_at <= ? LIMIT ?",
	)
		.bind(now, BATCH)
		.all<{ id: string }>();

	for (const share of results) {
		const { results: files } = await env.DB.prepare('SELECT * FROM share_files WHERE share_id = ?')
			.bind(share.id)
			.all<ShareFileRow>();

		for (const file of files) {
			await deleteObject(env, file.object_key);
		}

		await env.DB.prepare("UPDATE shares SET status = 'deleted' WHERE id = ?").bind(share.id).run();
		await env.DB.prepare('DELETE FROM share_files WHERE share_id = ?').bind(share.id).run();
	}

	return results.length;
}

CREATE TABLE IF NOT EXISTS shares (
	id TEXT PRIMARY KEY,
	created_at INTEGER NOT NULL,
	expires_at INTEGER NOT NULL,
	status TEXT NOT NULL CHECK (status IN ('uploading', 'ready', 'deleted')),
	max_downloads INTEGER,
	downloads INTEGER NOT NULL DEFAULT 0,
	reported INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS shares_expires_idx ON shares (expires_at);

CREATE TABLE IF NOT EXISTS share_files (
	share_id TEXT NOT NULL REFERENCES shares (id),
	object_key TEXT NOT NULL,
	name TEXT NOT NULL,
	size INTEGER NOT NULL,
	mime TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS share_files_share_idx ON share_files (share_id);

CREATE TABLE IF NOT EXISTS reports (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	share_id TEXT NOT NULL,
	reason TEXT NOT NULL,
	created_at INTEGER NOT NULL
);

