import Toast from '../components/ui/Toast.astro';

interface Props {
	title: string;
	description: string;
}

const { title, description } = Astro.props;
---

<!doctype html>
<html lang="id">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width, initial-scale=1" />
		<title>{title}</title>
		<meta name="description" content={description} />
		<meta property="og:title" content={title} />
		<meta property="og:description" content={description} />
		<meta property="og:type" content="website" />
		<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
		<meta name="generator" content={Astro.generator} />
		<script is:inline>
			(() => {
				try {
					const stored = localStorage.getItem('toolsman-theme');
					if (stored === 'light' || stored === 'dark') {
						document.documentElement.dataset.theme = stored;
					}
				} catch {
					/* tanpa akses penyimpanan, tema mengikuti sistem */
				}
			})();
		</script>
	</head>
	<body>
		<a class="skip-link" href="#konten">Langsung ke konten</a>
		<Header />
		<main id="konten"><slot /></main>
		<Footer />
		<Toast />
	</body>
</html>
---
import Layout from '../layouts/Layout.astro';
---

<Layout
	title="Halaman tidak ditemukan, Toolsman"
	description="Alamat yang kamu buka tidak ada di Toolsman."
>
	<section class="container prose-page">
		<h1>Halaman tidak ditemukan</h1>
		<p>
			Alamat ini tidak ada, mungkin salah ketik atau alatnya belum dibuat.
			Katalog di beranda memuat semua alat yang direncanakan.
		</p>
		<p><a class="btn btn--primary mt-4" href="/#katalog">Buka katalog alat</a></p>
	</section>
</Layout>
import type { ToolMeta } from './tool-types';
import { categories } from './tool-types';
import type { AstroComponentFactory } from 'astro/runtime/server/index.js';

const modules = import.meta.glob<{ meta: ToolMeta }>('../features/*/meta.ts', {
	eager: true,
});

const toolUIs = import.meta.glob<{ default: AstroComponentFactory }>(
	'../features/*/tool.astro',
	{ eager: true },
);

const categoryOrder = new Map(categories.map((item, index) => [item.id, index]));

export const tools: ToolMeta[] = Object.values(modules)
	.map((module) => module.meta)
	.sort((a, b) => {
		const byCategory =
			(categoryOrder.get(a.category) ?? 99) - (categoryOrder.get(b.category) ?? 99);
		return byCategory !== 0 ? byCategory : a.name.localeCompare(b.name, 'id');
	});

export function getTool(slug: string): ToolMeta | undefined {
	return tools.find((tool) => tool.slug === slug);
}

export function getToolUI(slug: string): AstroComponentFactory | null {
	return toolUIs[`../features/${slug}/tool.astro`]?.default ?? null;
}

export function relatedTools(tool: ToolMeta, count = 3): ToolMeta[] {
	const sameCategory = tools.filter(
		(item) => item.slug !== tool.slug && item.category === tool.category,
	);
	const others = tools.filter(
		(item) => item.slug !== tool.slug && item.category !== tool.category,
	);
	return [...sameCategory, ...others].slice(0, count);
}

