---
import Layout from '../../layouts/Layout.astro';
import Modal from '../../components/ui/Modal.astro';
import type { SharesDb, ShareFileRow, ShareRow } from '../../features/kirim-file/db';
import { presignDownload, type R2Env } from '../../features/kirim-file/r2';
import { viewShare } from '../../features/kirim-file/share-view';
import { formatBytes, formatRemaining } from '../../features/kirim-file/format';

export const prerender = false;

const ID_PATTERN = /^[0-9a-f]{32}$/;
const id = Astro.params.id ?? '';

interface Env extends R2Env {
	DB: SharesDb;
}

const env = (Astro.locals as { runtime?: { env: Env } }).runtime?.env;
const valid = ID_PATTERN.test(id) && Boolean(env);

const row = valid
	? await env!.DB.prepare('SELECT * FROM shares WHERE id = ?').bind(id).first<ShareRow>()
	: null;
const view = env ? viewShare(row, Date.now()) : { state: 'missing' as const, remainingMs: 0 };

const files =
	view.state === 'ok'
		? await env!.DB.prepare('SELECT * FROM share_files WHERE share_id = ?')
				.bind(id)
				.all<ShareFileRow>()
				.then(({ results }) =>
					Promise.all(
						results.map(async (file) => ({
							name: file.name,
							size: file.size,
							downloadUrl: await presignDownload(env!, file.object_key),
						})),
					),
				)
		: [];

if (view.state === 'expired') Astro.response.status = 410;
else if (view.state === 'missing') Astro.response.status = 404;
---

<Layout
	title={view.state === 'ok' ? `Unduh berkas, Toolsman` : 'Link tidak tersedia, Toolsman'}
	description="Halaman unduh berkas yang dibagikan lewat Toolsman. Link hilang sendiri sesuai masa berlakunya."
>
	<section class="container prose-page share-page">
		{
			view.state === 'missing' && (
				<>
					<h1>Link tidak ditemukan</h1>
					<p>
						Alamat ini salah, link-nya sudah dihapus, atau berkasnya belum selesai diunggah.
						Minta pengirim membuat link baru.
					</p>
					<p>
						<a class="btn btn--primary mt-4" href="/tools/kirim-file">
							Buat link sendiri
						</a>
					</p>
				</>
			)
		}

		{
			view.state === 'expired' && (
				<>
					<h1>Link sudah kedaluwarsa</h1>
					<p>
						Berkas dan link ini sudah dihapus otomatis. Kalau masih perlu, minta pengirim
						mengunggah ulang dengan masa berlaku lebih lama.
					</p>
					<p>
						<a class="btn btn--primary mt-4" href="/tools/kirim-file">
							Kirim berkas
						</a>
					</p>
				</>
			)
		}

		{
			view.state === 'ok' && (
				<>
					<h1>Berkas siap diunduh</h1>
					<p data-countdown>{formatRemaining(view.remainingMs)}.</p>
					<ul class="share-page__list">
						{files.map((file) => (
							<li class="share-page__item">
								<span>
									{file.name}
									<span class="share-page__size">{formatBytes(file.size)}</span>
								</span>
								<a class="btn btn--primary" href={file.downloadUrl} rel="noreferrer">
									Unduh
								</a>
							</li>
						))}
					</ul>
					<p class="field-hint">
						Tombol unduh berlaku 15 menit. Muat ulang halaman ini kalau sudah lewat.
					</p>
					<button type="button" class="btn btn--ghost" data-report-open>
						Laporkan link ini
					</button>

					<Modal id="report-modal" labelledby="report-title">
						<h2 id="report-title">Laporkan link</h2>
						<p class="field-hint">
							Tulis alasan singkat, misalnya isinya berbahaya atau bukan untuk dibagikan.
						</p>
						<form data-report-form class="share-page__report">
							<label class="field-label" for="report-reason">Alasan</label>
							<textarea
								id="report-reason"
								class="field-input"
								rows="3"
								maxlength="500"
								required></textarea>
							<div class="pane-actions">
								<button type="submit" class="btn btn--primary">Kirim laporan</button>
								<button type="button" class="btn btn--secondary" data-report-close>
									Batal
								</button>
							</div>
							<p class="field-hint" data-report-status aria-live="polite"></p>
						</form>
					</Modal>

					<script>
						const open = document.querySelector<HTMLButtonElement>('[data-report-open]');
						const dialog = document.getElementById('report-modal') as HTMLDialogElement | null;
						const close = document.querySelector<HTMLButtonElement>('[data-report-close]');
						const form = document.querySelector<HTMLFormElement>('[data-report-form]');
						const status = document.querySelector<HTMLElement>('[data-report-status]');

						open?.addEventListener('click', () => dialog?.showModal());
						close?.addEventListener('click', () => dialog?.close());

						form?.addEventListener('submit', async (event) => {
							event.preventDefault();
							if (!status) return;
							status.textContent = 'Mengirim laporan…';
							try {
								const response = await fetch(`/api/shares/${id}/report`, {
									method: 'POST',
									headers: { 'Content-Type': 'application/json' },
									body: JSON.stringify({
										reason: (document.getElementById('report-reason') as HTMLTextAreaElement).value,
									}),
								});
								if (!response.ok) throw new Error('Gagal mengirim laporan.');
								status.textContent = 'Laporan terkirim. Terima kasih.';
								form.reset();
							} catch {
								status.textContent = 'Laporan gagal dikirim. Coba lagi nanti.';
							}
						});
					</script>
				</>
			)
		}
	</section>
</Layout>

<style>
	.share-page__list {
		display: flex;
		flex-direction: column;
		gap: var(--space-2);
		margin: var(--space-4) 0;
		padding: 0;
		list-style: none;
	}

	.share-page__item {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		justify-content: space-between;
		gap: var(--space-3);
		padding: var(--space-3);
		border: 1px solid var(--border);
		border-radius: var(--radius-md);
		background: var(--surface);
	}

	.share-page__item > span {
		display: flex;
		flex-direction: column;
		gap: var(--space-1);
		min-width: 0;
		overflow-wrap: anywhere;
	}

	.share-page__size {
		color: var(--text-muted);
		font-size: 0.875rem;
	}

	.share-page__report {
		display: flex;
		flex-direction: column;
		gap: var(--space-3);
		margin-top: var(--space-3);
	}
</style>

