		const progress = files.map((_, i) => (current.done.has(i) ? 100 : 0));
		renderList(progress);

		for (const [index, file] of files.entries()) {
			if (current.done.has(index)) continue;
			const target = current.uploads[index];
			if (!target) throw new Error('Respons server tidak lengkap.');
			status.textContent = `Mengunggah ${file.name}…`;

			let attempt = 0;
			for (;;) {
				attempt += 1;
				try {
					activeUpload = putWithProgress(target.uploadUrl, file, file.type || 'application/octet-stream', (loaded, total) => {
						progress[index] = Math.round((loaded / total) * 100);
						renderList(progress);
					});
					await activeUpload.promise;
					activeUpload = null;
					break;
