					activeUpload = null;
					if (cancelled) throw error;
					const retryable = !(error instanceof UploadError) || error.status === undefined || error.status >= 500 || error.status === 0;
					if (!retryable || attempt >= 3) throw error;
					status.textContent = `Koneksi bermasalah. Mencoba lagi (${attempt + 1}/3)…`;
					await delay(1000 * attempt);
				}
			}
			progress[index] = 100;
			current.done.add(index);
			renderList(progress);
		}

		status.textContent = 'Menyelesaikan link…';
		const done = await fetch(`/api/shares/${current.id}/complete`, { method: 'POST' });
		if (!done.ok) throw new Error('Unggahan selesai, tapi link gagal disiapkan. Coba lagi.');
		session = null;
		status.textContent = '';
		await showResult(current.id, current.expiresAt, current.oneTime);
		toast('Link siap dibagikan.');
	} catch (error) {
		if (cancelled) {
			status.textContent = 'Unggahan dibatalkan. Tekan Coba lagi untuk melanjutkan dari berkas yang belum selesai.';
		} else if (error instanceof UploadError && error.status === 403) {
